// FreeLang v8 ML - Neural Network 레이어
import { Value } from './autodiff';

export class Neuron {
  w: Value[];
  b: Value;

  constructor(nin: number) {
    this.w = Array.from({ length: nin }, () => Value.from(Math.random() * 2 - 1));
    this.b = Value.from(0);
  }

  forward(x: Value[]): Value {
    let act = this.b;
    for (let i = 0; i < this.w.length; i++)
      act = act.add(this.w[i].mul(x[i]));
    return act.tanh();
  }

  params(): Value[] { return [...this.w, this.b]; }
}

export class Layer {
  neurons: Neuron[];

  constructor(nin: number, nout: number) {
    this.neurons = Array.from({ length: nout }, () => new Neuron(nin));
  }

  forward(x: Value[]): Value[] {
    return this.neurons.map(n => n.forward(x));
  }

  params(): Value[] { return this.neurons.flatMap(n => n.params()); }
}

export class MLP {
  layers: Layer[];

  constructor(nin: number, nouts: number[]) {
    const sizes = [nin, ...nouts];
    this.layers = [];
    for (let i = 0; i < nouts.length; i++)
      this.layers.push(new Layer(sizes[i], sizes[i + 1]));
  }

  forward(x: number[]): Value[] {
    let out: Value[] = x.map(v => Value.from(v));
    for (const layer of this.layers) out = layer.forward(out);
    return out;
  }

  params(): Value[] { return this.layers.flatMap(l => l.params()); }

  zeroGrad(): void {
    for (const p of this.params()) p.grad = 0;
  }
}

// SGD 옵티마이저
export class SGD {
  lr: number;
  constructor(lr = 0.01) { this.lr = lr; }

  step(params: Value[]): void {
    for (const p of params) p.data -= this.lr * p.grad;
  }
}

