// FreeLang v8 ML - XOR 학습 예제
import { MLP } from '../src/ml/nn';
import { Adam } from '../src/ml/optimizer';
import { mse } from '../src/ml/loss';

// XOR 데이터
const X = [[0,0],[0,1],[1,0],[1,1]];
const Y = [0, 1, 1, 0];

const model = new MLP(2, [4, 4, 1]);
const optim = new Adam(0.01);

for (let epoch = 0; epoch < 1000; epoch++) {
  const preds = X.map(x => model.forward(x));
  const loss = mse(preds.map(p => p[0]), Y);

  optim.zeroGrad(model.params());
  loss.backward();
  optim.step(model.params());

  if (epoch % 100 === 0)
    console.log(`Epoch ${epoch} | loss: ${loss.data.toFixed(6)}`);
}

console.log('\n=== XOR 결과 ===');
X.forEach((x, i) => {
  const pred = model.forward(x)[0].data;
  console.log(`${x} → ${pred.toFixed(4)} (정답: ${Y[i]})`);
});

