  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

// ======================================================
// 1. Lexer — ML 토큰
// ======================================================
console.log('\n[1] Lexer ML 토큰');

test('tensor 키워드 인식', () => {
  const { tokens } = new Lexer('tensor').tokenize();
  assert(tokens[0].type === TokenType.TENSOR, `got ${tokens[0].type}`);
});

test('grad 키워드 인식', () => {
  const { tokens } = new Lexer('grad').tokenize();
  assert(tokens[0].type === TokenType.GRAD, `got ${tokens[0].type}`);
});

test('with 키워드 인식', () => {
  const { tokens } = new Lexer('with').tokenize();
  assert(tokens[0].type === TokenType.WITH, `got ${tokens[0].type}`);
});

test('@ 행렬곱 연산자', () => {
  const { tokens } = new Lexer('A @ B').tokenize();
  assert(tokens[1].type === TokenType.MATMUL, `got ${tokens[1].type}`);
});

test('.T 전치 연산자', () => {
  const { tokens } = new Lexer('A.T').tokenize();
  assert(tokens[1].type === TokenType.TRANSPOSE, `got ${tokens[1].type}`);
});

test('Tensor 타입 키워드', () => {
  const { tokens } = new Lexer('Tensor').tokenize();
  assert(tokens[0].type === TokenType.TYPE_TENSOR, `got ${tokens[0].type}`);
});

test('f32 타입 키워드', () => {
  const { tokens } = new Lexer('f32').tokenize();
  assert(tokens[0].type === TokenType.TYPE_F32, `got ${tokens[0].type}`);
});

test('ML 복합 표현식 렉싱', () => {
  const src = 'let w: Tensor = randn(4, 3)\nlet y = w @ x';
  const { tokens, errors } = new Lexer(src).tokenize();
  assert(errors.length === 0, `에러: ${errors.map(e => e.message).join(',')}`);
  const matmulTok = tokens.find(t => t.type === TokenType.MATMUL);
  assert(matmulTok !== undefined, '@ 토큰 없음');
});

// ======================================================
// 2. Shape 타입 체커
// ======================================================
console.log('\n[2] Shape 타입 체커');

test('Tensor[3,4] 파싱', () => {
  const t = parseTensorType('Tensor[3,4]');
  assert(t !== null, '파싱 실패');
  assert(JSON.stringify(t!.shape) === JSON.stringify([3,4]), `shape: ${t!.shape}`);
});

test('Tensor[N,M] 심볼릭 파싱', () => {
  const t = parseTensorType('Tensor[N,M]');
  assert(t !== null, '파싱 실패');
  assert(t!.shape[0] === 'N' && t!.shape[1] === 'M', `shape: ${t!.shape}`);
});

test('[3,4] @ [4,2] → [3,2] 정상', () => {
  const { result, error } = checkMatmul('Tensor[3,4]', 'Tensor[4,2]');
  assert(error === null, `에러: ${error?.message}`);
  assert(JSON.stringify(result!.shape) === JSON.stringify([3,2]), `shape: ${result!.shape}`);
});

test('[3,4] @ [3,2] → shape 오류', () => {
  const { result, error } = checkMatmul('Tensor[3,4]', 'Tensor[3,2]');
  assert(error !== null, '오류가 발생해야 함');
  assert(error!.message.includes('불일치'), `메시지: ${error!.message}`);
});

test('[N,M] @ [M,K] → [N,K] 심볼릭', () => {
  const { result, error } = checkMatmul('Tensor[N,M]', 'Tensor[M,K]');
  assert(error === null, `에러: ${error?.message}`);
  assert(result!.shape[0] === 'N' && result!.shape[1] === 'K', `shape: ${result!.shape}`);
});

test('.T 전치: [3,4] → [4,3]', () => {
  const t = parseTensorType('Tensor[3,4]')!;
  const r = transposeShape(t);
  assert(JSON.stringify(r.shape) === JSON.stringify([4,3]), `shape: ${r.shape}`);
});

// ======================================================
// 3. XOR 학습 수렴
// ======================================================
console.log('\n[3] XOR 수렴');

test('XOR loss < 0.01 (1000 epoch)', () => {
  const X = [[0,0],[0,1],[1,0],[1,1]];
  const Y = [0, 1, 1, 0];
  const model = new MLP(2, [4, 4, 1]);
  const optim = new Adam(0.01);

  for (let e = 0; e < 1000; e++) {
    const preds = X.map(x => model.forward(x));
    const loss = mse(preds.map(p => p[0]), Y);
    optim.zeroGrad(model.params());
    loss.backward();
    optim.step(model.params());
  }

  const preds = X.map(x => model.forward(x)[0].data);
  const finalLoss = preds.reduce((s, p, i) => s + (p - Y[i]) ** 2, 0) / 4;
  assert(finalLoss < 0.01, `loss ${finalLoss.toFixed(6)} >= 0.01`);
});

test('XOR 정답률 4/4', () => {
  const X = [[0,0],[0,1],[1,0],[1,1]];
  const Y = [0, 1, 1, 0];
  const model = new MLP(2, [4, 4, 1]);
  const optim = new Adam(0.01);
  for (let e = 0; e < 1000; e++) {
    const preds = X.map(x => model.forward(x));
    const loss = mse(preds.map(p => p[0]), Y);
    optim.zeroGrad(model.params());
    loss.backward();
    optim.step(model.params());
  }
  let correct = 0;
  X.forEach((x, i) => {
    const pred = model.forward(x)[0].data;
    if (Math.round(pred) === Y[i]) correct++;
  });
  assert(correct === 4, `정답 ${correct}/4`);
});

// ======================================================
// 결과
// ======================================================
console.log(`\n${'='.repeat(40)}`);
console.log(`결과: ${passed}/${passed + failed} PASS`);
if (failed > 0) process.exit(1);

