// 배열/텐서 리터럴: [a,b] or [[1,2],[3,4]]
private parseArrayOrTensorLit(): Expr {
  const tok = this.advance(); // [
  const elements: Expr[] = [];
  if (!this.check(TokenType.RBRACKET)) {
    do {
      elements.push(this.parseExpr(0));
    } while (this.match(TokenType.COMMA));
  }
  this.expect(TokenType.RBRACKET, "expected ']'");

  // 모든 원소가 array_lit이면 → 2D tensor_lit
  if (elements.length > 0 && elements.every(e => e.kind === "array_lit")) {
    const rows = elements.length;
    const cols = (elements[0] as any).elements.length;
    const flat: Expr[] = [];
    for (const row of elements) {
      flat.push(...(row as any).elements);
    }
    return { kind: "tensor_lit", elements: flat, shape: [rows, cols], line: tok.line, col: tok.col };
  }

  return { kind: "array_lit", elements, line: tok.line, col: tok.col };
}

