// FreeLang v8 ML — Phase 2 Parser 테스트
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function parse(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  return { program, errors };
}

// ======================================================
// 1. Tensor 타입 어노테이션
// ======================================================
console.log('\n[1] Tensor 타입 어노테이션');

test('let w: Tensor[3,4] 파싱', () => {
  const { program, errors } = parse('let w: Tensor[3,4] = zeros(3,4)');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.kind === 'var_decl', `kind: ${decl.kind}`);
  assert(decl.type?.kind === 'tensor', `type.kind: ${decl.type?.kind}`);
  assert(JSON.stringify(decl.type?.shape) === JSON.stringify([3, 4]), `shape: ${decl.type?.shape}`);
});

test('let w: Tensor[N,M] 심볼릭', () => {
  const { program, errors } = parse('let w: Tensor[N,M] = zeros(0,0)');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.type?.shape[0] === 'N', `shape[0]: ${decl.type?.shape[0]}`);
  assert(decl.type?.shape[1] === 'M', `shape[1]: ${decl.type?.shape[1]}`);
});

test('Tensor[3,4]<f32> dtype 파싱', () => {
  const { program, errors } = parse('let w: Tensor[3,4]<f32> = zeros(3,4)');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.type?.dtype === 'f32', `dtype: ${decl.type?.dtype}`);
});

test('f32 스칼라 타입', () => {
  const { program, errors } = parse('let s: f32 = 3.14');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.type?.kind === 'f32', `type.kind: ${decl.type?.kind}`);
});

// ======================================================
// 2. @ matmul 연산자
// ======================================================
console.log('\n[2] @ matmul 연산자');

test('A @ B 파싱', () => {
  const { program, errors } = parse('let y = A @ B');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.init?.kind === 'matmul', `init.kind: ${decl.init?.kind}`);
  assert(decl.init?.left?.name === 'A', `left: ${decl.init?.left?.name}`);
  assert(decl.init?.right?.name === 'B', `right: ${decl.init?.right?.name}`);
});

test('A @ B @ C 좌결합', () => {
  const { program, errors } = parse('let y = A @ B @ C');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  // A @ B @ C → (A @ B) @ C
  assert(decl.init?.kind === 'matmul', `outer: ${decl.init?.kind}`);
  assert(decl.init?.left?.kind === 'matmul', `inner: ${decl.init?.left?.kind}`);
});

test('x + A @ B 우선순위', () => {
  const { program, errors } = parse('let y = x + A @ B');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  // + < @, 따라서 x + (A @ B)
  assert(decl.init?.kind === 'binary', `kind: ${decl.init?.kind}`);
  assert(decl.init?.op === '+', `op: ${decl.init?.op}`);
  assert(decl.init?.right?.kind === 'matmul', `right: ${decl.init?.right?.kind}`);
});

// ======================================================
// 3. .T 전치 연산자
// ======================================================
console.log('\n[3] .T 전치 연산자');

test('A.T 파싱', () => {
  const { program, errors } = parse('let t = A.T');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.init?.kind === 'transpose', `kind: ${decl.init?.kind}`);
  assert(decl.init?.operand?.name === 'A', `operand: ${decl.init?.operand?.name}`);
});

test('A.T @ B 연산자 조합', () => {
  const { program, errors } = parse('let y = A.T @ B');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.init?.kind === 'matmul', `kind: ${decl.init?.kind}`);
  assert(decl.init?.left?.kind === 'transpose', `left: ${decl.init?.left?.kind}`);
});

// ======================================================
// 4. 텐서 리터럴
// ======================================================
console.log('\n[4] 텐서 리터럴');

test('[[1,2],[3,4]] 2D tensor_lit', () => {
  const { program, errors } = parse('let m = [[1,2],[3,4]]');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.init?.kind === 'tensor_lit', `kind: ${decl.init?.kind}`);
  assert(JSON.stringify(decl.init?.shape) === JSON.stringify([2, 2]), `shape: ${decl.init?.shape}`);
  assert(decl.init?.elements?.length === 4, `elements: ${decl.init?.elements?.length}`);
});

test('[1,2,3] 1D array_lit (텐서 아님)', () => {
  const { program, errors } = parse('let v = [1,2,3]');
  assert(errors.length === 0, `파싱 에러: ${errors.map(e => e.message).join(',')}`);
  const decl = program.stmts[0] as any;
  assert(decl.init?.kind === 'array_lit', `kind: ${decl.init?.kind}`);
});

// ======================================================
// 5. with grad: {} 블록
// ======================================================
console.log('\n[5] with grad 블록');

