// FreeLang v8 ML — .fl8 로 XOR MLP 학습

print("=== XOR MLP (.fl8) ===")

// 데이터
let X0 = [0.0, 0.0]
let X1 = [0.0, 1.0]
let X2 = [1.0, 0.0]
let X3 = [1.0, 1.0]
let Y  = [0.0, 1.0, 1.0, 0.0]
let inputs = [X0, X1, X2, X3]

// 모델과 옵티마이저 생성
let model = MLP(2, 4, 4, 1)
let optim = Adam(0.01)

// 학습 루프
let epoch = 0
while epoch < 1000 {
  let i = 0
  while i < 4 {
    let x = inputs[i]
    let preds = model(x)
    let loss = mse(preds, [Y[i]])

    optim.zeroGrad(model.params())

    with grad: {
      loss.backward()
    }

    optim.step(model.params())
    i = i + 1
  }

  if epoch % 200 == 0 {
    let x0 = inputs[0]
    let p0 = model(x0)
    let l0 = mse(p0, [Y[0]])
    print("Epoch", epoch, "sample loss:", l0.data)
  }

  epoch = epoch + 1
}

print("학습 완료!")

// 최종 예측
print("=== 예측 결과 ===")
let correct = 0
let j = 0
while j < 4 {
  let x = inputs[j]
  let out = model(x)
  let pred_val = out[0].data
  let label = Y[j]
  let predicted = 0
  if pred_val > 0.5 {
    predicted = 1
  }
  if predicted == label {
    correct = correct + 1
  }
  print("pred:", pred_val, " 예측:", predicted, " 정답:", label)
  j = j + 1
}
print("정확도:", correct, "/ 4")

