  let out = model(x)
  let pred_val = out[0].data
  let label = Y[j]
  let predicted = 0
  if pred_val > 0.5 {
    predicted = 1
  }
  if predicted == label {
    correct = correct + 1
  }
  j = j + 1
}
  `;
