while epoch < 1000 {
  let i = 0
  while i < 4 {
    let x = inputs[i]
    let preds = model(x)
    let loss = mse(preds, [Y[i]])
    optim.zeroGrad(model.params())
    with grad: {
      loss.backward()
    }
    optim.step(model.params())
    i = i + 1
  }
  epoch = epoch + 1
}

let correct = 0
let j = 0
while j < 4 {
  let x = inputs[j]
  let out = model(x)
  let pred_val = out[0].data
  let label = Y[j]
  let predicted = 0
  if pred_val > 0.5 {
    predicted = 1
  }
  if predicted == label {
    correct = correct + 1
  }
  j = j + 1
}
  `;
  run(src);
  assert(true, '');
});

// ======================================================
// 결과
// ======================================================
console.log(`\n${'='.repeat(40)}`);
console.log(`결과: ${passed}/${passed + failed} PASS`);
if (failed > 0) process.exit(1);

