import { Value } from './autodiff';

// MSE Loss
export function mse(pred: Value[], target: number[]): Value {
  if (pred.length !== target.length) throw new Error('length 불일치');
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const diff = pred[i].add(Value.from(-target[i]));
    loss = loss.add(diff.pow(2));
  }
  return loss.mul(Value.from(1 / pred.length));
}

// Cross-Entropy Loss (binary)
export function binaryCrossEntropy(pred: Value[], target: number[]): Value {
  let loss = Value.from(0);
  for (let i = 0; i < pred.length; i++) {
    const p = pred[i];
    const y = target[i];
    // -[y*log(p) + (1-y)*log(1-p)]
    const t1 = Value.from(y).mul(Value.from(Math.log(Math.max(p.data, 1e-7))));
    const t2 = Value.from(1 - y).mul(Value.from(Math.log(Math.max(1 - p.data, 1e-7))));
    loss = loss.add(Value.from(-(t1.data + t2.data)));
  }
  return loss.mul(Value.from(1 / pred.length));
}

