// FreeLang v8 ML - DataLoader (배치, 셔플, 미니배치 학습)

export type Dataset = {
  X: number[][];
  y: number[][];
};

export type Batch = {
  X: number[][];
  y: number[][];
};

// ============================================================
// DataLoader
// ============================================================

export class DataLoader {
  private indices: number[];

  constructor(
    public dataset: Dataset,
    public batchSize: number = 32,
    public shuffle: boolean = true
  ) {
    this.indices = Array.from({ length: dataset.X.length }, (_, i) => i);
  }

  // 에포크마다 배치 목록 반환
  *batches(): Generator<Batch> {
    if (this.shuffle) fisherYates(this.indices);

    for (let i = 0; i < this.indices.length; i += this.batchSize) {
      const batchIdx = this.indices.slice(i, i + this.batchSize);
      yield {
        X: batchIdx.map(idx => this.dataset.X[idx]),
        y: batchIdx.map(idx => this.dataset.y[idx]),
      };
    }
  }

  get length(): number {
    return Math.ceil(this.dataset.X.length / this.batchSize);
  }

  get size(): number {
    return this.dataset.X.length;
  }
}

// ============================================================
// train/test split
// ============================================================

export function trainTestSplit(
  X: number[][], y: number[][],
  testRatio = 0.2,
  seed?: number
): { trainX: number[][], trainY: number[][], testX: number[][], testY: number[][] } {
  const n = X.length;
  const indices = Array.from({ length: n }, (_, i) => i);
  if (seed !== undefined) seededShuffle(indices, seed);
  else fisherYates(indices);

  const splitIdx = Math.floor(n * (1 - testRatio));
  const trainIdx = indices.slice(0, splitIdx);
  const testIdx  = indices.slice(splitIdx);

  return {
    trainX: trainIdx.map(i => X[i]),
    trainY: trainIdx.map(i => y[i]),
    testX:  testIdx.map(i => X[i]),
    testY:  testIdx.map(i => y[i]),
  };
}

// ============================================================
// 정규화 (Min-Max, Z-Score)
// ============================================================

export function minMaxNormalize(X: number[][]): { normalized: number[][], min: number[], max: number[] } {
  const features = X[0].length;
  const min = Array(features).fill(Infinity);
  const max = Array(features).fill(-Infinity);

  for (const row of X) {
    for (let j = 0; j < features; j++) {
      if (row[j] < min[j]) min[j] = row[j];
      if (row[j] > max[j]) max[j] = row[j];
    }
  }

  const normalized = X.map(row =>
    row.map((v, j) => max[j] === min[j] ? 0 : (v - min[j]) / (max[j] - min[j]))
  );
  return { normalized, min, max };
}

export function zScoreNormalize(X: number[][]): { normalized: number[][], mean: number[], std: number[] } {
  const features = X[0].length;
  const n = X.length;
  const mean = Array(features).fill(0);
  const std  = Array(features).fill(0);

  for (const row of X) for (let j = 0; j < features; j++) mean[j] += row[j];
  for (let j = 0; j < features; j++) mean[j] /= n;

  for (const row of X) for (let j = 0; j < features; j++) std[j] += (row[j] - mean[j]) ** 2;
  for (let j = 0; j < features; j++) std[j] = Math.sqrt(std[j] / n) || 1;

  const normalized = X.map(row =>
    row.map((v, j) => (v - mean[j]) / std[j])
  );
  return { normalized, mean, std };
}

// one-hot encoding
export function oneHot(labels: number[], numClasses: number): number[][] {
  return labels.map(l => {
    const row = Array(numClasses).fill(0);
    row[l] = 1;
    return row;
  });
}

// ============================================================
// 유틸리티
// ============================================================

function fisherYates(arr: number[]): void {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
}

function seededShuffle(arr: number[], seed: number): void {
  let s = seed;
  const rand = () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 2 ** 32; };
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
}

