// FreeLang v8 ML — Phase 4 ML stdlib 테스트
import { Value } from '../src/ml/autodiff';
import { Linear, ReLU, Sigmoid, Tanh, Softmax, Dropout, BatchNorm1d, Sequential, MLP } from '../src/ml/nn';
import { mse, mae, huber, binaryCrossEntropy, softmaxCrossEntropy, hingeLoss } from '../src/ml/loss';
import { DataLoader, trainTestSplit, minMaxNormalize, zScoreNormalize, oneHot } from '../src/ml/dataloader';
import { Trainer } from '../src/ml/trainer';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { Interpreter } from '../src/runtime/interpreter';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// ======================================================
// 1. Linear 레이어
// ======================================================
console.log('\n[1] Linear 레이어');

test('Linear forward shape', () => {
  const layer = new Linear(4, 3);
  const x = [1, 2, 3, 4].map(v => Value.from(v));
  const out = layer.forward(x);
  assert(out.length === 3, `output size: ${out.length}`);
});

test('Linear params count', () => {
  const layer = new Linear(4, 3);
  const p = layer.params();
  assert(p.length === 4 * 3 + 3, `params: ${p.length} (expected ${4 * 3 + 3})`);
});

test('Sequential forward', () => {
  const model = new Sequential([
    new Linear(2, 4),
    new ReLU(),
    new Linear(4, 1),
    new Sigmoid(),
  ]);
  const x = [0.5, 0.5].map(v => Value.from(v));
  const out = model.forward(x);
  assert(out.length === 1, `output: ${out.length}`);
  assert(out[0].data >= 0 && out[0].data <= 1, `sigmoid output 범위`);
});

test('Sequential params', () => {
  const model = new Sequential([new Linear(2, 4), new Linear(4, 1)]);
  const p = model.params();
  const expected = (2 * 4 + 4) + (4 * 1 + 1);
  assert(p.length === expected, `params: ${p.length} (expected ${expected})`);
});

test('Dropout train mode', () => {
  const drop = new Dropout(0.5);
  const x = Array(100).fill(1).map(v => Value.from(v));
  const out = drop.forward(x);
  const zeros = out.filter(v => v.data === 0).length;
  // 약 50% → 30~70 범위
  assert(zeros > 20 && zeros < 80, `dropout zeros: ${zeros}`);
});

test('BatchNorm1d forward', () => {
  const bn = new BatchNorm1d(4);
  const x = [1, 2, 3, 4].map(v => Value.from(v));
  const out = bn.forward(x);
  assert(out.length === 4, `output: ${out.length}`);
});

// ======================================================
// 2. 손실 함수
// ======================================================
console.log('\n[2] 손실 함수');

test('MAE loss', () => {
  const pred = [1.5, 2.5].map(v => Value.from(v));
  const target = [1.0, 2.0];
  const loss = mae(pred, target);
  assert(Math.abs(loss.data - 0.5) < 1e-6, `mae: ${loss.data}`);
});

test('Huber loss (작은 오차 → MSE)', () => {
  const pred = [1.3].map(v => Value.from(v));
  const target = [1.0];
  const loss = huber(pred, target, 1.0);
  const expected = 0.5 * 0.3 * 0.3;
  assert(Math.abs(loss.data - expected) < 1e-6, `huber: ${loss.data}`);
});

test('Huber loss (큰 오차 → MAE)', () => {
  const pred = [3.0].map(v => Value.from(v));
  const target = [0.0];
  const loss = huber(pred, target, 1.0);
  // delta*(|diff| - 0.5*delta) = 1*(3 - 0.5) = 2.5
  assert(Math.abs(loss.data - 2.5) < 1e-6, `huber large: ${loss.data}`);
});

test('Softmax cross-entropy', () => {
  const logits = [2.0, 1.0, 0.1].map(v => Value.from(v));
  const loss = softmaxCrossEntropy(logits, 0); // 클래스 0이 정답
  assert(loss.data >= 0, `ce loss < 0: ${loss.data}`);
  assert(loss.data < 2.0, `ce loss too high: ${loss.data}`);
});

test('Hinge loss', () => {
  const pred = [0.8, -0.5].map(v => Value.from(v));
  const target = [1.0, -1.0];
  const loss = hingeLoss(pred, target);
  // margin: max(0, 1-1*0.8)=0.2, max(0, 1-(-1)*(-0.5))=0.5 → avg=0.35
  assert(Math.abs(loss.data - 0.35) < 1e-6, `hinge: ${loss.data}`);
});

test('BCE backward 가능', () => {
  const pred = [0.7, 0.3].map(v => Value.from(v));
  const target = [1.0, 0.0];
  const loss = binaryCrossEntropy(pred, target);
  loss.backward();
  assert(true, '');
});

// ======================================================
// 3. DataLoader
// ======================================================
console.log('\n[3] DataLoader');

test('DataLoader 배치 생성', () => {
  const X = Array.from({ length: 100 }, (_, i) => [i * 0.01]);
  const y = X.map(x => [x[0] > 0.5 ? 1 : 0]);
  const loader = new DataLoader({ X, y }, 16, false);
  let count = 0;
  let total = 0;
  for (const batch of loader.batches()) {
    count++;
    total += batch.X.length;
  }
  assert(count === 7, `batch count: ${count}`);  // 100/16 = 7 (마지막 4개)
  assert(total === 100, `total: ${total}`);
});

test('trainTestSplit', () => {
  const X = Array.from({ length: 100 }, (_, i) => [i]);
  const y = X.map(x => [x[0] % 2]);
  const { trainX, testX } = trainTestSplit(X, y, 0.2, 42);
  assert(trainX.length === 80, `train: ${trainX.length}`);
  assert(testX.length === 20, `test: ${testX.length}`);
});

test('minMaxNormalize', () => {
  const X = [[0, 10], [5, 20], [10, 30]];
  const { normalized, min, max } = minMaxNormalize(X);
  assert(Math.abs(normalized[0][0] - 0.0) < 1e-6, `min: ${normalized[0][0]}`);
  assert(Math.abs(normalized[2][0] - 1.0) < 1e-6, `max: ${normalized[2][0]}`);
  assert(Math.abs(normalized[1][0] - 0.5) < 1e-6, `mid: ${normalized[1][0]}`);
});

test('zScoreNormalize', () => {
  const X = [[0], [2], [4]]; // mean=2, std≈1.63
  const { normalized, mean } = zScoreNormalize(X);
  assert(Math.abs(mean[0] - 2.0) < 1e-6, `mean: ${mean[0]}`);
  assert(Math.abs(normalized[1][0]) < 1e-6, `z-score of mean: ${normalized[1][0]}`);
});

test('oneHot encoding', () => {
  const labels = [0, 1, 2, 1];
  const encoded = oneHot(labels, 3);
  assert(JSON.stringify(encoded[0]) === JSON.stringify([1, 0, 0]), `[0]: ${encoded[0]}`);
  assert(JSON.stringify(encoded[2]) === JSON.stringify([0, 0, 1]), `[2]: ${encoded[2]}`);
});

// ======================================================
// 4. Trainer
// ======================================================
console.log('\n[4] Trainer');

test('Trainer fit XOR', () => {
  const model = new MLP(2, [4, 4, 1]);
  const trainer = new Trainer(model, {
    epochs: 200,
    lr: 0.01,
    batchSize: 4,
    verbose: false,
    logEvery: 50,
  });

  const trainData = {
    X: [[0,0],[0,1],[1,0],[1,1]],
    y: [[0], [1], [1], [0]],
  };

  const history = trainer.fit(trainData);
  assert(history.trainLoss.length === 200, `history: ${history.trainLoss.length}`);
  const lastLoss = history.trainLoss[history.trainLoss.length - 1];
  assert(lastLoss < 0.5, `최종 loss 너무 높음: ${lastLoss.toFixed(4)}`);
});

test('Trainer evaluate', () => {
  const model = new MLP(2, [4, 1]);
  const trainer = new Trainer(model, { epochs: 1, verbose: false });
  const data = { X: [[0,0],[1,1]], y: [[0],[1]] };
  const loss = trainer.evaluate(data);
  assert(typeof loss === 'number', `loss type: ${typeof loss}`);
});

test('Trainer predict', () => {
  const model = new MLP(2, [4, 1]);
  const trainer = new Trainer(model, { epochs: 1, verbose: false });
  const preds = trainer.predict([[0, 0], [1, 1]]);
  assert(preds.length === 2, `preds: ${preds.length}`);
  assert(preds[0].length === 1, `pred[0].length: ${preds[0].length}`);
});

// ======================================================
// 5. .fl8 인터프리터 — 새 레이어 사용
// ======================================================
console.log('\n[5] .fl8 새 레이어');

test('Linear 레이어 .fl8', () => {
  run(`
let layer = Linear(4, 2)
let x = [1.0, 2.0, 3.0, 4.0]
let out = layer(x)
  `);
  assert(true, '');
});

test('ReLU/Sigmoid .fl8', () => {
  run(`
let relu = ReLU()
let sig = Sigmoid()
let x = [-1.0, 0.0, 1.0]
let r = relu(x)
let s = sig(x)
  `);
  assert(true, '');
});

test('MAE 손실 .fl8', () => {
  run(`
let preds = [1.5, 2.5]
let targets = [1.0, 2.0]
let loss = mae(preds, targets)
print("mae:", loss.data)
  `);
  assert(true, '');
});

test('one_hot .fl8', () => {
  run(`
let labels = [0, 1, 2]
let encoded = one_hot(labels, 3)
print("one_hot:", encoded)
  `);
  assert(true, '');
});

test('normalize .fl8', () => {
  run(`
let X = [[0.0, 10.0], [5.0, 20.0], [10.0, 30.0]]
let n = normalize(X)
print("normalized:", n)
  `);
  assert(true, '');
});

test('Binary classifier .fl8 실행', () => {
  const src = `
let model = MLP(2, 8, 1)
let optim = Adam(0.01)
let inputs = [[0.1, 0.1], [0.9, 0.9]]
let labels = [1.0, 0.0]
let epoch = 0
while epoch < 50 {
  let i = 0
  while i < 2 {
    let x = inputs[i]
    let out = model(x)
    let loss = mse(out, [labels[i]])
    optim.zeroGrad(model.params())
    with grad: { loss.backward() }
    optim.step(model.params())
    i = i + 1
  }
  epoch = epoch + 1
}
print("Binary classifier 완료")
  `;
  run(src);
  assert(true, '');
});

// ======================================================
// 6. Softmax 분류기 (3-class)
// ======================================================
console.log('\n[6] Softmax 분류기');

test('3-class 수렴', () => {
  // 간단한 3-class 분류
  const model = new Sequential([
    new Linear(2, 8),
    new ReLU(),
    new Linear(8, 3),
  ]);

  const X = [
    [1, 0], [1.1, 0.1], [0.9, -0.1],   // class 0
    [0, 1], [0.1, 1.1], [-0.1, 0.9],   // class 1
    [1, 1], [1.1, 1.1], [0.9, 0.9],    // class 2
  ];
  const Y = [0, 0, 0, 1, 1, 1, 2, 2, 2];

  const optim = new (require('../src/ml/optimizer').Adam)(0.01);
  for (let epoch = 0; epoch < 200; epoch++) {
    for (let i = 0; i < X.length; i++) {
      const inp = X[i].map(v => Value.from(v));
      const out = model.forward(inp);
      const loss = softmaxCrossEntropy(out, Y[i]);
      optim.zeroGrad(model.params());
      loss.backward();
      optim.step(model.params());
    }
  }

  // 정확도 확인
  let correct = 0;
  for (let i = 0; i < X.length; i++) {
    const inp = X[i].map(v => Value.from(v));
    const out = model.forward(inp);
    const pred = out.map(v => v.data);
    if (pred.indexOf(Math.max(...pred)) === Y[i]) correct++;
  }
  assert(correct >= 7, `3-class 정확도: ${correct}/9`);
});

// ======================================================
// 결과
// ======================================================
console.log(`\n${'='.repeat(40)}`);
console.log(`결과: ${passed}/${passed + failed} PASS`);
if (failed > 0) process.exit(1);

