// ============================================================

export function positionalEncoding(seqLen: number, dModel: number): number[][] {
  const pe: number[][] = Array.from({ length: seqLen }, () => Array(dModel).fill(0));
  for (let pos = 0; pos < seqLen; pos++) {
    for (let i = 0; i < dModel; i += 2) {
      const angle = pos / Math.pow(10000, i / dModel);
      pe[pos][i]     = Math.sin(angle);
      if (i + 1 < dModel) pe[pos][i + 1] = Math.cos(angle);
    }
  }
  return pe;
}

// ============================================================
// 헬퍼 함수
// ============================================================

function makeWeight(rows: number, cols: number, scale: number): Value[][] {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () =>
      Value.from((Math.random() * 2 - 1) * scale)
    )
  );
}

function matmul2D(A: Value[][], W: Value[][]): Value[][] {
  const rows = A.length;
  const cols = W[0].length;
  const inner = W.length;
  return Array.from({ length: rows }, (_, i) =>
    Array.from({ length: cols }, (_, j) => {
      let s = Value.from(0);
      for (let k = 0; k < inner; k++) s = s.add(A[i][k].mul(W[k][j]));
      return s;
    })
  );
}

function softmaxValues(vals: Value[]): Value[] {
  const maxVal = Math.max(...vals.map(v => v.data));
  const exps = vals.map(v => Math.exp(v.data - maxVal));
  const sum = exps.reduce((a, b) => a + b, 0);
  // 근사 softmax — 정확한 역전파 대신 data만 업데이트
  return exps.map(e => Value.from(e / sum));
}

