// FreeLang v8 ML — 미니 언어 모델 (.fl8)
// 캐릭터 수준 텍스트 생성

print("=== MiniGPT Language Model (.fl8) ===")

// 학습 텍스트
let text = "the quick brown fox jumps over the lazy dog the fox"

// 토크나이저 준비
let tok = CharTokenizer()
tok.fit(text)
print("Vocab size:", tok.vocabSize)

// 인코딩
let ids = tok.encode(text)
print("Token count:", len(ids))

// MiniGPT 생성 (vocab, d_model, heads, layers, max_seq)
let gpt = MiniGPT(tok.vocabSize, 16, 2, 2, 32)
print("모델 생성:", gpt)

// 학습
print("학습 중...")
let losses = gpt.train(ids, 100, 0.005)
print("초기 loss:", losses[0])
print("최종 loss:", losses[99])

// 텍스트 생성
let seed_text = "the"
let seed_ids = tok.encode(seed_text)
print("시드:", seed_text)

let generated = gpt.generate(seed_ids, 20)
let output = tok.decode(generated)
print("생성 결과:", output)

print("완료!")

