     7→import { Parser } from "./parser/parser";
     8→import { Interpreter } from "./runtime/interpreter";
     9→
    10→function main() {
    11→  const args = process.argv.slice(2);
    12→
    13→  if (args.length === 0) {
    14→    console.log("사용법: fl8 <파일.fl8>");
    15→    console.log("       fl8 -e '<코드>'");
    16→    process.exit(1);
    17→  }
    18→
    19→  let source: string;
    20→  let filename: string;
    21→
    22→  if (args[0] === "-e") {
    23→    source = args[1] ?? "";
    24→    filename = "<stdin>";
    25→  } else {
    26→    filename = args[0];
    27→    if (!fs.existsSync(filename)) {
    28→      console.error(`파일 없음: ${filename}`);
    29→      process.exit(1);
    30→    }
    31→    source = fs.readFileSync(filename, "utf-8");
    32→  }
    33→
    34→  // Lex
    35→  const lexer = new Lexer(source);
    36→  const { tokens, errors: lexErrors } = lexer.tokenize();
    37→
    38→  if (lexErrors.length > 0) {
    39→    for (const e of lexErrors) {
    40→      console.error(`[Lex 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
    41→    }
    42→    process.exit(1);
    43→  }
    44→
