#!/usr/bin/env python3
# fl8_bridge.py — FreeLang v8 Python Bridge Server
# JSON stdin/stdout 프로토콜

import sys
import json
import traceback


def handle(payload):
    op = payload.get("op", "eval")

    if op == "eval":
        code = payload.get("code", "")
        ns = {}
        try:
            exec(code, ns)
            scalars = {k: v for k, v in ns.items()
                      if isinstance(v, (int, float)) and not k.startswith('_')}
            strings = {k: v for k, v in ns.items()
                      if isinstance(v, str) and not k.startswith('_')}
            return {"success": True, "scalars": scalars, "strings": strings}
        except Exception as e:
            return {"success": False, "error": str(e), "traceback": traceback.format_exc()}

    elif op == "numpy":
        try:
            import numpy as np
            inputs = payload.get("inputs", {})
            code = payload.get("code", "")
            ns = {"np": np}
            for name, arr in inputs.items():
                ns[name] = np.array(arr["data"], dtype=arr["dtype"]).reshape(arr["shape"])
            exec(code, ns)
            outputs = {}
            for k, v in ns.items():
                if isinstance(v, np.ndarray) and not k.startswith('_'):
                    outputs[k] = {
                        "shape": list(v.shape),
                        "dtype": str(v.dtype),
                        "data": v.flatten().tolist()
                    }
            return {"success": True, "outputs": outputs}
        except ImportError:
            return {"success": False, "error": "numpy가 설치되어 있지 않습니다"}
        except Exception as e:
            return {"success": False, "error": str(e), "traceback": traceback.format_exc()}

    elif op == "torch":
        try:
            import torch
            import numpy as np
            model_path = payload.get("model_path")
            inputs_list = payload.get("inputs", [])
            model = torch.load(model_path, map_location='cpu')
            model.eval()
            results = []
            with torch.no_grad():
                for inp in inputs_list:
                    t = torch.tensor(inp["data"], dtype=torch.float32).reshape(inp["shape"])
                    out = model(t)
                    results.append({
                        "shape": list(out.shape),
                        "dtype": "float32",
                        "data": out.numpy().flatten().tolist()
                    })
            return {"success": True, "outputs": results}
        except ImportError:
            return {"success": False, "error": "torch가 설치되어 있지 않습니다"}
        except Exception as e:
            return {"success": False, "error": str(e), "traceback": traceback.format_exc()}

    elif op == "convert":
        # FL8 weights → PyTorch state_dict 변환
        try:
            import torch
            weights = payload.get("weights", {})
            output_path = payload.get("output_path", "model.pt")
            state_dict = {}
            for name, data in weights.items():
                state_dict[name] = torch.tensor(data, dtype=torch.float32)
            torch.save(state_dict, output_path)
            return {"success": True, "path": output_path}
        except ImportError:
            return {"success": False, "error": "torch가 설치되어 있지 않습니다"}
        except Exception as e:
            return {"success": False, "error": str(e)}

    elif op == "info":
        # 환경 정보 반환
        info = {
            "python": sys.version,
            "numpy": False,
            "torch": False,
            "torch_version": None,
            "numpy_version": None,
        }
        try:
            import numpy as np
            info["numpy"] = True
            info["numpy_version"] = np.__version__
        except ImportError:
            pass
        try:
            import torch
            info["torch"] = True
            info["torch_version"] = torch.__version__
            info["cuda"] = torch.cuda.is_available()
        except ImportError:
            pass
        return {"success": True, "info": info}

    else:
        return {"success": False, "error": f"알 수 없는 op: {op}"}


if __name__ == "__main__":
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            payload = json.loads(line)
            response = handle(payload)
        except json.JSONDecodeError as e:
            response = {"success": False, "error": f"JSON 파싱 실패: {e}"}
        print(json.dumps(response, ensure_ascii=False), flush=True)

