#!/usr/bin/env ts-node
// FreeLang v8 ML — .fl8 파일 실행기 (fl8 CLI)
// Phase 6: install/publish/build 서브커맨드 추가

import * as fs from "fs";
import * as path from "path";
import { Lexer } from "./lexer/lexer";
import { Parser } from "./parser/parser";
import { Interpreter } from "./runtime/interpreter";
import { PackageManager } from "./pkg/package-manager";
import { buildForBrowser, buildForWorker } from "./wasm/wasm_target";
import { PythonBridge } from "./bridge/python_bridge";

const VERSION = "8.0.0";

function printHelp() {
  console.log(`FreeLang v8 ML — fl8 CLI v${VERSION}

사용법:
  fl8 <파일.fl8>                  .fl8 파일 실행
  fl8 -e '<코드>'                 인라인 코드 실행

패키지 관리:
  fl8 init [이름]                 fl8.json 초기화
  fl8 install                     모든 의존성 설치
  fl8 install <패키지> [버전]     특정 패키지 설치
  fl8 publish                     패키지 배포
  fl8 list                        설치된 패키지 목록

빌드:
  fl8 build browser <입력.fl8> <출력폴더>   브라우저 번들 생성
  fl8 build worker  <입력.fl8> <출력폴더>   Web Worker 번들 생성

브릿지:
  fl8 python info                 Python 환경 정보
  fl8 python run <코드>           Python 코드 실행

옵션:
  --version, -v                   버전 출력
  --help, -h                      이 도움말 출력`);
}

function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    printHelp();
    process.exit(1);
  }

  const cmd = args[0];

  // 버전/도움말
  if (cmd === "--version" || cmd === "-v") {
    console.log(`fl8 v${VERSION}`);
    return;
  }
  if (cmd === "--help" || cmd === "-h") {
    printHelp();
    return;
  }

  // ─── 패키지 관리 ───────────────────────────────────────────

  if (cmd === "init") {
    const pm = new PackageManager();
    const name = args[1];
    try {
      const manifest = pm.init(name ? { name } : {});
      console.log(`✓ fl8.json 생성: ${manifest.name} v${manifest.version}`);
    } catch (e: any) {
      console.error("오류:", e.message);
      process.exit(1);
    }
    return;
  }

  if (cmd === "install") {
    const pm = new PackageManager();
    const pkgName = args[1];
    const version = args[2];
    try {
      const result = pm.install(pkgName, version);
      if (result.name === "__all__") {
        console.log(`✓ ${result.count ?? 0}개 패키지 설치 완료`);
      } else {
        console.log(`✓ ${result.name}@${result.version} 설치 완료`);
        console.log(`  resolved: ${result.resolved}`);
      }
    } catch (e: any) {
      console.error("설치 오류:", e.message);
      process.exit(1);
    }
    return;
  }

  if (cmd === "publish") {
    const pm = new PackageManager();
    try {
      const result = pm.publish();
      if (result.success) {
        console.log(`✓ ${result.name}@${result.version} 배포 완료`);
        console.log(`  registry: ${result.registry}`);
        console.log(`  파일 수: ${result.files}`);
        console.log(`  URL: ${result.url}`);
      }
    } catch (e: any) {
      console.error("배포 오류:", e.message);
      process.exit(1);
    }
    return;
  }

  if (cmd === "list") {
    const pm = new PackageManager();
    const pkgs = pm.list();
    if (pkgs.length === 0) {
      console.log("설치된 패키지 없음");
    } else {
      console.log("패키지 목록:");
      for (const pkg of pkgs) {
        const status = pkg.installed ? `v${pkg.installed}` : "미설치";
        console.log(`  ${pkg.name.padEnd(20)} ${pkg.required.padEnd(10)} [${status}]`);
      }
    }
    return;
  }

  // ─── 빌드 ──────────────────────────────────────────────────

  if (cmd === "build") {
    const target = args[1]; // 'browser' | 'worker'
    const entry = args[2];
    const output = args[3] ?? "dist";

    if (!target || !entry) {
      console.error("사용법: fl8 build browser|worker <입력.fl8> <출력폴더>");
      process.exit(1);
    }

    if (!fs.existsSync(entry)) {
      console.error(`파일 없음: ${entry}`);
      process.exit(1);
    }

    try {
      let result;
      if (target === "browser") {
        result = buildForBrowser(entry, output);
      } else if (target === "worker") {
        result = buildForWorker(entry, output);
      } else {
        console.error(`알 수 없는 타겟: ${target} (browser|worker)`);
        process.exit(1);
      }

      if (result.success) {
        console.log(`✓ ${target} 번들 빌드 완료`);
        console.log(`  출력: ${output}/`);
        console.log(`  파일:`);
        for (const f of result.files) {
          const size = fs.statSync(f).size;
          console.log(`    ${path.relative(output, f).padEnd(30)} ${(size / 1024).toFixed(1)}KB`);
        }
        console.log(`  총 크기: ${(result.size / 1024).toFixed(1)}KB`);
      } else {
        console.error("빌드 실패:", result.error);
        process.exit(1);
      }
    } catch (e: any) {
      console.error("빌드 오류:", e.message);
      process.exit(1);
    }
    return;
  }

  // ─── Python 브릿지 ─────────────────────────────────────────

  if (cmd === "python") {
    const subCmd = args[1];
    const bridge = new PythonBridge();

    if (subCmd === "info") {
      const available = bridge.isAvailable();
      console.log(`Python: ${available ? bridge.version() : "미설치"}`);
      if (available) {
        console.log(`NumPy:  ${bridge.hasNumpy() ? "설치됨" : "미설치"}`);
        console.log(`PyTorch: ${bridge.hasTorch() ? "설치됨" : "미설치"}`);
      }
      return;
    }

    if (subCmd === "run") {
      const code = args.slice(2).join(" ");
      if (!code) {
        console.error("사용법: fl8 python run <Python 코드>");
        process.exit(1);
      }
      const result = bridge.eval(code);
      if (result.success) {
        if (result.stdout) process.stdout.write(result.stdout);
        if (result.data && Object.keys(result.data).length > 0) {
          console.log("결과:", JSON.stringify(result.data, null, 2));
        }
      } else {
        console.error("Python 오류:", result.error);
        process.exit(1);
      }
      return;
    }

    console.error(`알 수 없는 python 서브커맨드: ${subCmd}`);
    process.exit(1);
  }

  // ─── .fl8 실행 ─────────────────────────────────────────────

  let source: string;
  let filename: string;

  if (cmd === "-e") {
    source = args[1] ?? "";
    filename = "<stdin>";
  } else {
    filename = cmd;
    if (!fs.existsSync(filename)) {
      console.error(`파일 없음: ${filename}`);
      process.exit(1);
    }
    source = fs.readFileSync(filename, "utf-8");
  }

  // Lex
  const lexer = new Lexer(source);
  const { tokens, errors: lexErrors } = lexer.tokenize();

  if (lexErrors.length > 0) {
    for (const e of lexErrors) {
      console.error(`[Lex 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
    }
    process.exit(1);
  }

  // Parse
  const parser = new Parser(tokens);
  const { program, errors: parseErrors } = parser.parse();

  if (parseErrors.length > 0) {
    for (const e of parseErrors) {
      console.error(`[파서 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
    }
    process.exit(1);
  }

  // Interpret
  const interp = new Interpreter();
  try {
    interp.run(program);
  } catch (e: any) {
    console.error(`[런타임 오류] ${e.message}`);
    process.exit(1);
  }
}

main();

