test('generateBridgeScript: 스크립트 생성', () => {
  const script = generateBridgeScript();
  assert(script.includes('import json'), 'json import 없음');
  assert(script.includes('def handle'), 'handle 함수 없음');
  assert(script.includes('"numpy"'), 'numpy op 없음');
  assert(script.includes('"torch"'), 'torch op 없음');
});

// ======================================================
// 5. WASM 타겟 — 브라우저 번들
// ======================================================
console.log('\n[5] WASM 타겟 — 브라우저/Worker 번들');

let tmpDir5 = '';
let testFl8Path = '';

// 테스트용 .fl8 파일 생성
function setupWasmTest() {
  tmpDir5 = makeTmpDir();
  testFl8Path = path.join(tmpDir5, 'test.fl8');
  fs.writeFileSync(testFl8Path, 'print("Hello, FL8 WASM!")\nlet x = 42\nprint(x)');
}

setupWasmTest();

test('buildForBrowser: 번들 파일 생성', () => {
  const outDir = path.join(tmpDir5, 'browser-out');
