// ============================================================
// AdamW (Adam + Weight Decay 분리)
// ============================================================

export class AdamW implements Optimizer {
  private t = 0;
  private m = new Map<Value, number>();
  private v = new Map<Value, number>();
  private scheduler?: LRScheduler;

  constructor(
    public lr = 0.001,
    public beta1 = 0.9,
    public beta2 = 0.999,
    public eps = 1e-8,
    public weightDecay = 0.01
  ) {}

  setScheduler(s: LRScheduler): this {
    this.scheduler = s;
    return this;
  }

  currentLR(): number {
    return this.scheduler ? this.scheduler.getLR(this.t) : this.lr;
  }

  step(params: Value[]): void {
    this.t++;
    const lr = this.currentLR();

    for (const p of params) {
      const g = p.grad;
      const m = (this.m.get(p) ?? 0) * this.beta1 + (1 - this.beta1) * g;
      const v = (this.v.get(p) ?? 0) * this.beta2 + (1 - this.beta2) * g * g;
      this.m.set(p, m);
      this.v.set(p, v);

      const mHat = m / (1 - Math.pow(this.beta1, this.t));
      const vHat = v / (1 - Math.pow(this.beta2, this.t));

      // AdamW: weight decay는 gradient에 더하지 않고 직접 적용
      p.data -= lr * mHat / (Math.sqrt(vHat) + this.eps) + lr * this.weightDecay * p.data;
