// FreeLang v8 ML — Phase 8 타입 시스템 테스트
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { typeCheck } from '../src/types/type_checker';
import { TypeEnv, T, typeToString, typeEqual, makeBuiltinEnv, FL8Type } from '../src/types/type_env';
import { typeMismatch, undefinedVar, wrongArity, noField } from '../src/types/type_error';
import { Interpreter } from '../src/runtime/interpreter';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

// FL8 소스 → 타입 체크 결과
function check(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors: parseErrors } = new Parser(tokens).parse();
  if (parseErrors.length > 0) throw new Error(`파서: ${parseErrors[0].message}`);
  return typeCheck(program);
}

// FL8 소스 → 오류 없음 검증
function expectOk(src: string): ReturnType<typeof typeCheck> {
  const result = check(src);
  if (result.errors.length > 0) {
    throw new Error(`예상치 못한 타입 오류:\n  ${result.errors.map(e => e.message).join('\n  ')}`);
  }
  return result;
}

// FL8 소스 → 특정 오류 포함 검증
function expectError(src: string, kind: string): ReturnType<typeof typeCheck> {
  const result = check(src);
  const found = result.errors.some(e => e.kind === kind);
  if (!found) {
    const got = result.errors.map(e => e.kind).join(', ') || '없음';
    throw new Error(`'${kind}' 오류 기대, 실제: [${got}]`);
  }
  return result;
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// ======================================================
// 1. FL8Type & TypeEnv
// ======================================================
console.log('\n[1] FL8Type & TypeEnv');

test('T 생성자: number', () => {
  const t = T.num();
  assert(t.tag === 'number', `tag: ${t.tag}`);
});

test('T 생성자: array', () => {
  const t = T.array(T.num());
  assert(t.tag === 'array', `tag: ${t.tag}`);
  assert((t as any).elem.tag === 'number', `elem: ${(t as any).elem.tag}`);
});

test('T 생성자: tensor', () => {
  const t = T.tensor([2, 3]);
  assert(t.tag === 'tensor', `tag: ${t.tag}`);
  assert((t as any).shape[0] === 2, `shape: ${(t as any).shape}`);
});

test('T 생성자: fn', () => {
  const t = T.fn([T.num(), T.str()], T.bool());
  assert(t.tag === 'fn', `tag: ${t.tag}`);
  assert((t as any).params.length === 2, `params: ${(t as any).params.length}`);
});

test('typeToString: number', () => {
  assert(typeToString(T.num()) === 'number', typeToString(T.num()));
});

test('typeToString: array<number>', () => {
  assert(typeToString(T.array(T.num())) === 'Array<number>', typeToString(T.array(T.num())));
});

test('typeToString: tensor', () => {
  const s = typeToString(T.tensor([2, 3]));
  assert(s.includes('Tensor'), `tensor: ${s}`);
  assert(s.includes('2') && s.includes('3'), `shape: ${s}`);
});

test('typeToString: fn', () => {
  const s = typeToString(T.fn([T.num()], T.str()));
  assert(s.includes('->'), `fn: ${s}`);
  assert(s.includes('number'), `param: ${s}`);
  assert(s.includes('string'), `ret: ${s}`);
});

test('typeEqual: 동일 태그', () => {
  assert(typeEqual(T.num(), T.num()), 'num == num');
  assert(typeEqual(T.bool(), T.bool()), 'bool == bool');
  assert(!typeEqual(T.num(), T.str()), 'num != str');
});

test('typeEqual: array 원소 비교', () => {
  assert(typeEqual(T.array(T.num()), T.array(T.num())), 'array<num>');
  assert(!typeEqual(T.array(T.num()), T.array(T.str())), 'array<num> != array<str>');
});

test('typeEqual: tensor wildcard ?', () => {
  const a = T.tensor([2, '?']);
  const b = T.tensor([2, 3]);
  assert(typeEqual(a, b), 'tensor wildcard 허용');
});

test('TypeEnv: define & lookup', () => {
  const env = new TypeEnv();
  env.define('x', T.num());
  const t = env.lookup('x');
  assert(t?.tag === 'number', `lookup: ${t?.tag}`);
});

test('TypeEnv: child scope 상속', () => {
  const parent = new TypeEnv();
  parent.define('x', T.num());
  const child = parent.child();
  assert(child.lookup('x')?.tag === 'number', '상속 실패');
});

test('TypeEnv: child scope 차단 없음', () => {
  const parent = new TypeEnv();
  parent.define('x', T.num());
  const child = parent.child();
  child.define('x', T.str());  // 자식에서 재정의
  assert(child.lookup('x')?.tag === 'string', '자식 shadow 실패');
  assert(parent.lookup('x')?.tag === 'number', '부모 영향 없어야 함');
});

test('makeBuiltinEnv: print 정의됨', () => {
  const env = makeBuiltinEnv();
  const t = env.lookup('print');
  assert(t?.tag === 'fn', `print: ${t?.tag}`);
});

test('makeBuiltinEnv: zeros, ones, randn', () => {
  const env = makeBuiltinEnv();
  assert(env.lookup('zeros')?.tag === 'fn', 'zeros');
  assert(env.lookup('ones')?.tag === 'fn', 'ones');
  assert(env.lookup('randn')?.tag === 'fn', 'randn');
});

test('makeBuiltinEnv: MiniGPT, CharTokenizer', () => {
  const env = makeBuiltinEnv();
  assert(env.lookup('MiniGPT')?.tag === 'fn', 'MiniGPT');
  assert(env.lookup('CharTokenizer')?.tag === 'fn', 'CharTokenizer');
});

// ======================================================
// 2. 타입 오류 생성자
// ======================================================
console.log('\n[2] 타입 오류 생성자');

test('typeMismatch: 메시지 포함', () => {
  const e = typeMismatch('number', 'string', 1, 1);
  assert(e.kind === 'type_mismatch', `kind: ${e.kind}`);
  assert(e.message.includes('number'), `msg: ${e.message}`);
  assert(e.message.includes('string'), `msg: ${e.message}`);
});

test('undefinedVar: 변수명 포함', () => {
  const e = undefinedVar('foo', 3, 5);
  assert(e.kind === 'undefined_variable', `kind: ${e.kind}`);
  assert(e.message.includes('foo'), `msg: ${e.message}`);
  assert(e.line === 3 && e.col === 5, `loc: ${e.line}:${e.col}`);
});

test('wrongArity: 수 포함', () => {
  const e = wrongArity('add', 2, 3, 1, 1);
  assert(e.kind === 'wrong_arity', `kind: ${e.kind}`);
  assert(e.message.includes('2'), `msg: ${e.message}`);
  assert(e.message.includes('3'), `msg: ${e.message}`);
});

test('noField: 필드명 포함', () => {
  const e = noField('MLP', 'nonexistent', 1, 1);
  assert(e.kind === 'no_field', `kind: ${e.kind}`);
  assert(e.message.includes('nonexistent'), `msg: ${e.message}`);
});

test('TypeErrorReport: toString 포맷', () => {
  const e = undefinedVar('bar', 5, 10);
  const s = e.toString();
  assert(s.includes('5:10'), `loc: ${s}`);
  assert(s.includes('bar'), `name: ${s}`);
});

// ======================================================
// 3. 타입 체커 — 정상 케이스
// ======================================================
console.log('\n[3] 타입 체커 — 정상 케이스');

test('숫자 리터럴', () => {
  const { env } = expectOk(`let x = 42`);
  const t = env.lookup('x');
  assert(t?.tag === 'number', `x: ${t?.tag}`);
});

test('문자열 리터럴', () => {
  const { env } = expectOk(`let s = "hello"`);
  assert(env.lookup('s')?.tag === 'string', 's 타입');
});

test('불리언 리터럴', () => {
  const { env } = expectOk(`let b = true`);
  assert(env.lookup('b')?.tag === 'bool', 'b 타입');
});

test('산술 표현식', () => {
  const { env } = expectOk(`let y = 1 + 2 * 3`);
  assert(env.lookup('y')?.tag === 'number', 'y 타입');
});

test('문자열 연결', () => {
  const { env } = expectOk(`let s = "hello" + " world"`);
  assert(env.lookup('s')?.tag === 'string', 's 타입');
});

test('배열 리터럴', () => {
  const { env } = expectOk(`let arr = [1, 2, 3]`);
  const t = env.lookup('arr');
  assert(t?.tag === 'array', `arr: ${t?.tag}`);
  assert((t as any)?.elem?.tag === 'number', `elem: ${(t as any)?.elem?.tag}`);
});

test('빈 배열', () => {
  const { env } = expectOk(`let arr = []`);
  assert(env.lookup('arr')?.tag === 'array', 'arr 타입');
});

test('변수 참조', () => {
  expectOk(`
let x = 10
let y = x + 5
  `);
});

test('if 조건문', () => {
  expectOk(`
let x = 1
if x > 0 {
  let y = x + 1
}
  `);
});

test('while 루프', () => {
  expectOk(`
let i = 0
while i < 10 {
  i = i + 1
}
  `);
});

test('for 루프', () => {
  expectOk(`
let arr = [1, 2, 3]
for x in arr {
  let y = x + 1
}
  `);
});

test('내장함수 len', () => {
  expectOk(`
let arr = [1, 2, 3]
let n = len(arr)
  `);
});

test('내장함수 print', () => {
  expectOk(`print("hello")`);
});

test('내장함수 zeros/ones', () => {
  expectOk(`
let a = zeros(3, 4)
let b = ones(2, 2)
  `);
});

test('MiniGPT 생성', () => {
  const { env } = expectOk(`let gpt = MiniGPT(20, 8, 2, 1, 16)`);
  assert(env.lookup('gpt')?.tag === 'gpt', `gpt: ${env.lookup('gpt')?.tag}`);
});

test('CharTokenizer 생성', () => {
  const { env } = expectOk(`let tok = CharTokenizer()`);
  assert(env.lookup('tok')?.tag === 'tokenizer', `tok: ${env.lookup('tok')?.tag}`);
});

test('GPT 메서드 접근', () => {
  expectOk(`
let gpt = MiniGPT(20, 8, 2, 1, 16)
let ids = [1, 2, 3]
let next = gpt.predict(ids)
  `);
});

test('Tokenizer 메서드 접근', () => {
  expectOk(`
let tok = CharTokenizer()
tok.fit("hello")
let ids = tok.encode("hello")
  `);
});

// ======================================================
// 4. 타입 체커 — 오류 케이스
// ======================================================
console.log('\n[4] 타입 체커 — 오류 케이스');

test('미정의 변수', () => {
  expectError(`let x = undefined_var`, 'undefined_variable');
});

test('인수 수 불일치 (너무 많음)', () => {
  expectError(`
fn add(a: f32, b: f32) -> f32 { return a + b }
let r = add(1, 2, 3)
  `, 'wrong_arity');
});

test('인수 수 불일치 (너무 적음)', () => {
  expectError(`
fn mul(a: f32, b: f32) -> f32 { return a * b }
let r = mul(1)
  `, 'wrong_arity');
});

test('호출 불가 타입', () => {
  expectError(`
let x = 42
let y = x(1, 2)
  `, 'not_callable');
});

// ======================================================
// 5. typeCheck API
// ======================================================
console.log('\n[5] typeCheck API');

test('ok: true/false', () => {
  const r1 = check(`let x = 1`);
  assert(r1.ok, '정상 코드 ok=false');

  const r2 = check(`let x = bad_var`);
  assert(!r2.ok, '오류 코드 ok=true');
});

test('errors 배열', () => {
  const r = check(`
let a = bad1
let b = bad2
let c = bad3
  `);
  assert(r.errors.length >= 3, `오류 수: ${r.errors.length}`);
});

test('env 반환', () => {
  const { env } = check(`let x = 42`);
  assert(env !== null, 'env null');
  assert(env.lookup('x')?.tag === 'number', 'x 타입');
});

test('복수 오류 수집 (파싱 중단 없음)', () => {
  const r = check(`
let a = 1
let b = undef1
let c = undef2
let d = a + b
  `);
  // 오류가 있어도 a와 d는 정의됨
  assert(r.env.lookup('a')?.tag === 'number', 'a 정의됨');
});

test('함수 선언 후 타입 등록', () => {
  const { env } = check(`
fn double(x: f32) -> f32 { return x * 2.0 }
  `);
  const ft = env.lookup('double');
  assert(ft?.tag === 'fn', `double: ${ft?.tag}`);
});

test('중첩 스코프 변수', () => {
  expectOk(`
let x = 1
if x > 0 {
  let y = x + 1
  let z = y * 2
}
  `);
});

test('배열 인덱싱 타입 — number elem', () => {
  const { env } = check(`
let arr = [1, 2, 3]
let v = arr[0]
  `);
  assert(env.lookup('v')?.tag === 'number', `v: ${env.lookup('v')?.tag}`);
});

test('문자열 + 숫자 → string', () => {
  const { env } = check(`let s = "x=" + 42`);
  // 이 경우 문자열 연결로 처리 가능 (런타임에서도 동일)
  assert(env.lookup('s') !== undefined, 's 정의');
});

// ======================================================
// 6. ML 타입 특화 체크
// ======================================================
console.log('\n[6] ML 타입 특화 체크');

test('MLP 타입 태그', () => {
  const { env } = check(`let m = MLP([2, 4, 1])`);
  assert(env.lookup('m')?.tag === 'mlp', `m: ${env.lookup('m')?.tag}`);
});

test('Adam 타입 태그', () => {
  const { env } = check(`let opt = Adam(0.01)`);
  assert(env.lookup('opt')?.tag === 'adam', `opt: ${env.lookup('opt')?.tag}`);
});

test('GPT generate 반환 타입', () => {
  const { env } = check(`
let gpt = MiniGPT(20, 8, 2, 1, 16)
let out = gpt.generate([1, 2], 5)
  `);
  // generate → array<number>
  const t = env.lookup('out');
  assert(t !== undefined, 'out 정의');
});

test('Tokenizer vocabSize 필드', () => {
  const { env } = check(`
let tok = CharTokenizer()
let v = tok.vocabSize
  `);
  const t = env.lookup('v');
  assert(t?.tag === 'number', `vocabSize: ${t?.tag}`);
});

test('tensor matmul 결과 타입', () => {
  const { env } = check(`
let a = zeros(3, 4)
let b = zeros(4, 2)
let c = a @ b
  `);
  const t = env.lookup('c');
  assert(t?.tag === 'tensor', `matmul 결과: ${t?.tag}`);
});

test('positional_encoding 반환 타입', () => {
  const { env } = check(`let pe = positional_encoding(8, 16)`);
  assert(env.lookup('pe') !== undefined, 'pe 정의');
});

// ======================================================
// 7. .fl8 인터프리터 + 타입 체크 파이프라인
