  assert((t as any)?.elem?.tag === 'number', `elem: ${(t as any)?.elem?.tag}`);
});

test('빈 배열', () => {
  const { env } = expectOk(`let arr = []`);
  assert(env.lookup('arr')?.tag === 'array', 'arr 타입');
});

test('변수 참조', () => {
  expectOk(`
let x = 10
let y = x + 5
  `);
});

test('if 조건문', () => {
  expectOk(`
