test('DB + Collections 조합: 단어 빈도 카운터', () => {
  const db = new FL8Db();
  db.createTable('words', ['id', 'word', 'count']);
  const texts = ['hello world hello', 'world foo bar hello'];
  const freq = new FL8HashMap<string, number>();
  for (const t of texts) {
    for (const w of t.split(' ')) {
      freq.set(w, (freq.getOr(w, 0) as number) + 1);
    }
  }
  for (const [word, count] of freq.entries()) {
    db.insert('words', { word, count });
  }
  assert(db.count('words') === 4, `단어 수: ${db.count('words')}`);
  const hello = db.select('words', { word: 'hello' }).rows;
  assert(hello[0].count === 3, `hello 빈도: ${hello[0].count}`);
});

test('PriorityQueue: 다익스트라 시뮬레이션', () => {
  // 간단한 최단 경로 시뮬레이션
  const pq = new FL8PriorityQueue<{ node: string; dist: number }>();
  const dist = new FL8HashMap<string, number>();
  const graph: Record<string, [string, number][]> = {
    A: [['B', 1], ['C', 4]],
    B: [['C', 2], ['D', 5]],
    C: [['D', 1]],
    D: [],
  };
  pq.enqueue({ node: 'A', dist: 0 }, 0);
  dist.set('A', 0);
  while (!pq.isEmpty()) {
    const { node, dist: d } = pq.dequeue()!;
    for (const [next, w] of graph[node] ?? []) {
      const nd = d + w;
      if (!dist.has(next) || dist.getOr(next, Infinity)! > nd) {
        dist.set(next, nd);
        pq.enqueue({ node: next, dist: nd }, nd);
      }
    }
  }
  assert(dist.get('D') === 4, `A→D 최단: ${dist.get('D')} (expected 4)`);
});

test('FS + DB: CSV → DB 로드', () => {
  const csvPath = path.join(TMP, 'data.csv');
  FL8_FS.write(csvPath, 'name,score\nAlice,90\nBob,85\nCarol,95');
  const csv = FL8_FS.readCsv ? FL8_FS.readCsv!(csvPath) : null;
  // readCsv가 없는 경우 직접 파싱
  const lines = fs.readFileSync(csvPath, 'utf-8').split('\n').filter(Boolean);
  const headers = lines[0].split(',');
  const db = new FL8Db();
  db.createTable('scores', ['id', ...headers]);
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split(',');
    const row: Record<string, unknown> = {};
    headers.forEach((h, idx) => { row[h] = isNaN(Number(vals[idx])) ? vals[idx] : Number(vals[idx]); });
    db.insert('scores', row as any);
  }
  assert(db.count('scores') === 3, 'CSV→DB 로드 실패');
  const top = db.select('scores', { name: 'Carol' }).rows[0];
  assert(top.score === 95, `Carol 점수: ${top.score}`);
});

test('Queue + FS: 배치 처리 시뮬레이션', () => {
  const q = new FL8Queue<string>();
  const logPath = path.join(TMP, 'batch.log');
  FL8_FS.write(logPath, '');
  const tasks = ['task1', 'task2', 'task3', 'task4', 'task5'];
  tasks.forEach(t => q.enqueue(t));
  const processed: string[] = [];
  while (!q.isEmpty()) {
    const task = q.dequeue()!;
    FL8_FS.append(logPath, `${task}\n`);
    processed.push(task);
  }
  assert(processed.length === 5, '처리 수 오류');
  const log = FL8_FS.read(logPath)!;
  assert(log.includes('task3'), '로그 누락');
});

// ============================================================
// 정리
// ============================================================
fs.rmSync(TMP, { recursive: true, force: true });

console.log(`\n${'='.repeat(50)}`);
console.log(`Phase 9 결과: ${passed} PASS / ${failed} FAIL`);
if (failed > 0) process.exit(1);

