print("입력: foo(123)")
print("토큰 타입:", toks2)

// 예상: [2,5,1,6] = IDENT LPAREN NUM RPAREN
if len(toks2) == 4 {
  print("토큰 수 확인: PASS")
} else {
  print("토큰 수 확인: FAIL")
}

print("")
