// FreeLang v8 ML — Self-Hosting Phase 10
// FL8로 작성된 미니 렉서 (숫자, 식별자, 연산자, 문자열 토큰화)
// 출력: 토큰 타입과 값을 공백으로 구분한 문자열

// ─── 문자 분류 헬퍼 ───────────────────────────────────────────

fn is_digit(ch: f32) -> f32 {
  // ch는 ASCII 코드값
  // '0'=48, '9'=57
  if ch >= 48 {
    if ch <= 57 {
      return 1
    }
  }
  return 0
}

fn is_alpha(ch: f32) -> f32 {
  // 'a'=97 'z'=122 'A'=65 'Z'=90 '_'=95
  if ch >= 97 {
    if ch <= 122 {
      return 1
    }
  }
  if ch >= 65 {
    if ch <= 90 {
      return 1
    }
  }
  if ch == 95 {
    return 1
  }
  return 0
}

fn is_alnum(ch: f32) -> f32 {
  if is_alpha(ch) == 1 {
    return 1
  }
  if is_digit(ch) == 1 {
    return 1
  }
  return 0
}

fn is_space(ch: f32) -> f32 {
  // ' '=32 '\t'=9 '\n'=10 '\r'=13
  if ch == 32 { return 1 }
  if ch == 9  { return 1 }
  if ch == 10 { return 1 }
  if ch == 13 { return 1 }
  return 0
}

// ─── 렉서 핵심 ────────────────────────────────────────────────
// 입력: ASCII 코드 배열, 출력: 토큰 타입 배열 (1=NUM,2=IDENT,3=OP,4=STR,5=LPAREN,6=RPAREN)

fn tokenize(codes: [f32]) -> [f32] {
  let result = []
  let i = 0
  let n = len(codes)

  while i < n {
    let ch = codes[i]

    // 공백 스킵
    if is_space(ch) == 1 {
      i = i + 1
    } else {
      // 숫자
      if is_digit(ch) == 1 {
        push(result, 1)  // NUM
        while i < n {
          if is_digit(codes[i]) == 1 {
            i = i + 1
          } else {
            if codes[i] == 46 {  // '.'
              i = i + 1
            } else {
              i = n  // break
            }
          }
        }
        i = n
      } else {
        // 식별자 / 키워드
        if is_alpha(ch) == 1 {
          push(result, 2)  // IDENT
          while i < n {
            if is_alnum(codes[i]) == 1 {
              i = i + 1
            } else {
              i = n
            }
          }
          i = n
        } else {
          // 연산자
          if ch == 43 { push(result, 3) i = i + 1 }  // '+'
          if ch == 45 { push(result, 3) i = i + 1 }  // '-'
          if ch == 42 { push(result, 3) i = i + 1 }  // '*'
          if ch == 47 { push(result, 3) i = i + 1 }  // '/'
          if ch == 61 { push(result, 3) i = i + 1 }  // '='
          if ch == 60 { push(result, 3) i = i + 1 }  // '<'
          if ch == 62 { push(result, 3) i = i + 1 }  // '>'
          if ch == 40 { push(result, 5) i = i + 1 }  // '('
          if ch == 41 { push(result, 6) i = i + 1 }  // ')'
          if ch == 59 { push(result, 3) i = i + 1 }  // ';'
        }
      }
    }
  }

  return result
}

// ─── 테스트 ───────────────────────────────────────────────────

print("=== FL8 Self-Hosting: 렉서 ===")

// "42 + x * 3" → ASCII 코드 배열
