let ok2 = check("10 - 3", r2, 7)

// 테스트 3: 6 * 7  → 42
let r3 = eval_expr([1, 3, 1], [6, 2, 7])
let ok3 = check("6 * 7", r3, 42)

// 테스트 4: 15 / 3  → 5
let r4 = eval_expr([1, 3, 1], [15, 3, 3])
let ok4 = check("15 / 3", r4, 5)

// 테스트 5: 2 + 3 * 4  → 14  (우선순위: * 먼저)
