// 단일 숫자: 42 → 42
let ok13 = check("42", eval_tokens([1,42]), 42)

// 0 + 0 → 0
let ok14 = check("0 + 0", eval_tokens([1,0, 3,0, 1,0]), 0)

// 1000 * 1000 → 1000000
