  let n = len(prog)
  let running = 1
  let output = []

  while running == 1 {
    if ip >= n { running = 0 }
    else {
      let op = prog[ip]

      if op == 0 {
        // PUSH val
        ip = ip + 1
        push(stack, prog[ip])
        ip = ip + 1
      } else {
        if op == 1 {
          // LOAD var_id
          ip = ip + 1
          let vid = prog[ip]
          push(stack, env_get(env, vid))
          ip = ip + 1
        } else {
          if op == 2 {
            // STORE var_id
            ip = ip + 1
            let vid2 = prog[ip]
            let top = pop(stack)
            env_set(env, vid2, top)
            ip = ip + 1
          } else {
            if op == 3 {
              // ADD
              let b = pop(stack)
              let a = pop(stack)
              push(stack, a + b)
              ip = ip + 1
            } else {
              if op == 4 {
                // SUB
                let b2 = pop(stack)
                let a2 = pop(stack)
                push(stack, a2 - b2)
                ip = ip + 1
              } else {
                if op == 5 {
                  // MUL
                  let b3 = pop(stack)
                  let a3 = pop(stack)
                  push(stack, a3 * b3)
                  ip = ip + 1
                } else {
                  if op == 6 {
                    // DIV
                    let b4 = pop(stack)
                    let a4 = pop(stack)
                    push(stack, a4 / b4)
                    ip = ip + 1
                  } else {
                    if op == 7 {
                      // JMP_IF_FALSE offset
                      ip = ip + 1
                      let offset = prog[ip]
                      ip = ip + 1
                      let cond = pop(stack)
                      if cond == 0 {
                        ip = ip + int(offset)
                      }
                    } else {
                      if op == 8 {
                        // CMP_LT
                        let b5 = pop(stack)
                        let a5 = pop(stack)
                        if a5 < b5 { push(stack, 1) }
                        else       { push(stack, 0) }
                        ip = ip + 1
                      } else {
                        if op == 9 {
                          // CMP_EQ
                          let b6 = pop(stack)
                          let a6 = pop(stack)
                          if a6 == b6 { push(stack, 1) }
                          else        { push(stack, 0) }
                          ip = ip + 1
                        } else {
                          if op == 10 {
                            // PRINT
                            let pv = stack[len(stack) - 1]
                            push(output, pv)
                            ip = ip + 1
                          } else {
                            if op == 11 {
                              // HALT
                              running = 0
                            } else {
                              if op == 12 {
                                // NEG
                                let tv = pop(stack)
                                push(stack, 0 - tv)
                                ip = ip + 1
                              } else {
                                if op == 13 {
                                  // CMP_GT
                                  let b7 = pop(stack)
                                  let a7 = pop(stack)
                                  if a7 > b7 { push(stack, 1) }
                                  else       { push(stack, 0) }
                                  ip = ip + 1
                                } else {
                                  // 알 수 없는 명령어 → 중단
                                  running = 0
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  return output
}

// ─── 검증 헬퍼 ────────────────────────────────────────────────

fn check_num(label: str, got: f32, want: f32) -> f32 {
  if got == want {
    print("  PASS:", label, "→", got)
    return 1
  }
  print("  FAIL:", label, "got", got, "want", want)
  return 0
}

fn check_arr(label: str, got: [f32], want: [f32]) -> f32 {
  if len(got) != len(want) {
    print("  FAIL:", label, "len got", len(got), "want", len(want))
    return 0
  }
  let i = 0
  let ok = 1
  while i < len(got) {
    if got[i] != want[i] { ok = 0 }
    i = i + 1
  }
  if ok == 1 {
    print("  PASS:", label, "→", got)
    return 1
  }
  print("  FAIL:", label, "got", got, "want", want)
  return 0
}

