// 0,1=PUSH3  2,3=STORE0
// 4,5=LOAD0  6,7=PUSH5  8=CMP_LT
// 9,10=JMPF 13  (거짓이면 ip=13→HALT)
// 11,12=PUSH1  실제론 ip=11
// 아, 배열 인덱스:
// [0]0,[1]3, [2]2,[3]0, [4]1,[5]0, [6]0,[7]5, [8]9,
// [9]8,[10]14, [11]0,[12]1, [13]12, [14]14
