// T6: sum(1..5) = 15  — 루프
// sum=0(var0), i=1(var1)
// 루프 시작 ip=8:
//   LOAD1, PUSH5, CMP_GT(11)
//   JMPF → if i>5 is false(=0) → jump to end
//   (거짓=i<=5이면 루프 계속)
// if i>5(=1, 참): JMPF 아무것도 안 함 → 다음 HALT
// if i<=5(=0, 거짓): JMPF → 루프 본체로 점프
//
// 배열 인덱스:
// [0]0,[1]0  PUSH 0
// [2]2,[3]0  STORE0 (sum=0)
// [4]0,[5]1  PUSH 1
// [6]2,[7]1  STORE1 (i=1)
// --- 루프체크 ip=8 ---
// [8]1,[9]1    LOAD1 (i)
// [10]0,[11]5  PUSH 5
// [12]11       CMP_GT
// [13]8,[14]17 JMPF 17  (i>5가 0이면 → ip=17 루프본체)
// [15]12       PRINT (sum)... 아니, print는 나중에
// wait: i>5이 참(1)이면 JMPF 안 함→[15]로 → HALT
//       i>5이 거짓(0)이면 JMPF → ip=17 (루프본체)
// [15]1,[16]0  LOAD0 (sum) — 루프 탈출 후 출력
// 아, 루프 탈출 후 sum을 출력해야...
// 구조:
//   check: if i>5 → goto END
//   body: sum+=i, i++, goto check
//   END: print sum, halt
//
// [0]0,0  [2]2,0   → sum=0
// [4]0,1  [6]2,1   → i=1
// [8]1,1 [10]0,5 [12]11   → i>5?
// [13]8,[14]35     JMPF 35  (false=i<=5 → ip=35 본체)
// [15]1,0 [17]12 [18]14    → LOAD sum, PRINT, HALT (루프 탈출)
// --- 본체 ip=19... 아니면 ---
// 구조 다시:
//   if NOT (i>5) → 본체  (= if i<=5)
//   CMP_GT → JMPF body_addr (0이면 본체)
//   → HALT (루프 탈출)
//   body: sum+=i, i++, JMP check

// 계산:
// [0]0,[1]0  [2]2,[3]0      (sum=0)
// [4]0,[5]1  [6]2,[7]1      (i=1)
// [8]=루프시작: LOAD1
// [8]1,[9]1
// [10]0,[11]5
// [12]11  CMP_GT
// [13]8,[14]17  JMPF 17  (i<=5이면 → 본체 ip=17, i>5이면 다음→[15])
// [15]1,[16]0  LOAD sum
// [16]12  PRINT   -- 잠깐, [16]은 이미 LOAD0의 값
// 아, LOAD는 2칸이므로:
// [15]1  [16]0 → [17]12 PRINT → [18]14 HALT
// --- 본체 ip=19 ---  아, JMPF가 17을 가리키면 [17]은 PRINT
// 다시: ip=17이 본체 시작이어야 함
// [15,16,17,18] = LOAD0, PRINT, HALT
// 그러면 본체는 ip=17이 PRINT가 됨... 안됨
//
// 명확하게:
// [0..7]: 초기화 (8칸)
// [8]: 루프 시작
// [8..12]: check (5칸)
// [13,14]: JMPF body_ip (2칸)
// [15,16]: LOAD0 (sum) (2칸)
// [17]: PRINT
// [18]: HALT
// --- 본체 (ip=19) ---
// [19,20]: LOAD0 (sum)
// [21,22]: LOAD1 (i)
// [23]: ADD
// [24,25]: STORE0 (sum)
// [26,27]: LOAD1 (i)
// [28,29]: PUSH1
// [30]: ADD
// [31,32]: STORE1 (i)
// [33,34]: JMP 8 (체크로)
// 총 35칸
// JMPF addr = 19

let loop_prog = [
  0,0, 2,0,
  0,1, 2,1,
