// FreeLang v8 ML — Phase 10 자체 호스팅 증명 테스트
import { Interpreter } from '../src/runtime/interpreter';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import * as fs from 'fs';
import * as path from 'path';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function assertEqual<T>(a: T, b: T, msg?: string) {
  const m = msg ?? `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`;
  if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(m);
}

// FL8 소스 실행 → 마지막 표현식 결과
function runFL8(src: string): unknown {
  const interp = new Interpreter();
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  return interp.run(program);
}

// FL8 소스 실행 → 숫자 결과
function runNum(src: string): number {
  const result = runFL8(src) as any;
  if (result?.tag === 'number') return result.val;
  if (result?.tag === 'array') return result.val.map((v: any) => v.val);
  throw new Error(`숫자 아님: ${JSON.stringify(result)}`);
}

// FL8 소스 실행 → 배열 결과 (숫자)
function runArr(src: string): number[] {
  const result = runFL8(src) as any;
  if (result?.tag === 'array') return result.val.map((v: any) => v.val ?? v);
  if (result?.tag === 'number') return [result.val];
  throw new Error(`배열 아님: ${JSON.stringify(result?.tag)}`);
}

// .fl8 파일 로드
function loadFL8(filename: string): string {
  return fs.readFileSync(path.join(__dirname, '..', 'examples', filename), 'utf-8');
}

// .fl8 파일 → 인터프리터 + 추가 소스 실행
function runFL8File(filename: string, extra = ''): Interpreter {
  const src = loadFL8(filename) + '\n' + extra;
  const interp = new Interpreter();
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  interp.run(program);
  return interp;
}

// ============================================================
// 1. 렉서 자체 호스팅 (selfhost_lexer.fl8)
// ============================================================
console.log('\n── 렉서 자체 호스팅 ──');

const LEXER_SRC = loadFL8('selfhost_lexer.fl8');

test('렉서: "42 + x * 3" → [NUM,OP,IDENT,OP,NUM]=[1,3,2,3,1]', () => {
  const src = LEXER_SRC + `
tokenize([52, 50, 32, 43, 32, 120, 32, 42, 32, 51])
`;
  const result = runArr(src);
  assertEqual(result, [1, 3, 2, 3, 1]);
});

test('렉서: "foo(123)" → [IDENT,LPAREN,NUM,RPAREN]=[2,5,1,6]', () => {
  const src = LEXER_SRC + `
tokenize([102, 111, 111, 40, 49, 50, 51, 41])
`;
  const result = runArr(src);
  assertEqual(result, [2, 5, 1, 6]);
});

test('렉서: "3.14 + 2" → [NUM,OP,NUM]=[1,3,1]', () => {
  const src = LEXER_SRC + `
tokenize([51, 46, 49, 52, 32, 43, 32, 50])
`;
  const result = runArr(src);
  assertEqual(result, [1, 3, 1]);
});

test('렉서: "a_b + c1" → [IDENT,OP,IDENT]=[2,3,2]', () => {
  const src = LEXER_SRC + `
tokenize([97, 95, 98, 32, 43, 32, 99, 49])
`;
  const result = runArr(src);
  assertEqual(result, [2, 3, 2]);
});

test('렉서: 단일 숫자 "7" → [NUM]=[1]', () => {
  const src = LEXER_SRC + `
tokenize([55])
`;
  const result = runArr(src);
  assertEqual(result, [1]);
});

test('렉서: "x=" → [IDENT,OP]=[2,3]', () => {
  const src = LEXER_SRC + `
tokenize([120, 61])
`;
  const result = runArr(src);
  assertEqual(result, [2, 3]);
});

test('렉서: is_digit("5"=53) → 1', () => {
  const src = LEXER_SRC + `
is_digit(53)
`;
  const result = runNum(src);
  assert(result === 1, `is_digit: ${result}`);
});

test('렉서: is_digit("a"=97) → 0', () => {
  const src = LEXER_SRC + `
is_digit(97)
`;
  const result = runNum(src);
  assert(result === 0, `is_digit: ${result}`);
});

test('렉서: is_alpha("Z"=90) → 1', () => {
  const src = LEXER_SRC + `
is_alpha(90)
`;
  const result = runNum(src);
  assert(result === 1, `is_alpha: ${result}`);
});

test('렉서: is_space(" "=32) → 1', () => {
  const src = LEXER_SRC + `
is_space(32)
`;
  const result = runNum(src);
  assert(result === 1, `is_space: ${result}`);
});

// ============================================================
// 2. 산술 평가기 자체 호스팅 (selfhost_eval.fl8)
// ============================================================
console.log('\n── 산술 평가기 자체 호스팅 ──');

const EVAL_SRC = loadFL8('selfhost_eval.fl8');

function evalExpr(tokens: number[]): number {
  const tokStr = '[' + tokens.join(',') + ']';
  const src = EVAL_SRC + `\neval_tokens(${tokStr})`;
  return runNum(src);
}

test('eval: 3 + 4 = 7', () => {
  assertEqual(evalExpr([1,3, 3,0, 1,4]), 7);
});
test('eval: 10 - 3 = 7', () => {
  assertEqual(evalExpr([1,10, 3,1, 1,3]), 7);
});
test('eval: 6 * 7 = 42', () => {
  assertEqual(evalExpr([1,6, 3,2, 1,7]), 42);
});
test('eval: 15 / 3 = 5', () => {
  assertEqual(evalExpr([1,15, 3,3, 1,3]), 5);
});
test('eval: 2+3*4 = 14 (우선순위)', () => {
  assertEqual(evalExpr([1,2, 3,0, 1,3, 3,2, 1,4]), 14);
});
test('eval: (2+3)*4 = 20 (괄호)', () => {
  assertEqual(evalExpr([5,0, 1,2, 3,0, 1,3, 6,0, 3,2, 1,4]), 20);
});
test('eval: 10-2-3 = 5 (좌결합)', () => {
  assertEqual(evalExpr([1,10, 3,1, 1,2, 3,1, 1,3]), 5);
});
test('eval: 100/5/4 = 5 (좌결합)', () => {
  assertEqual(evalExpr([1,100, 3,3, 1,5, 3,3, 1,4]), 5);
});
test('eval: (1+2)*(3+4) = 21', () => {
  assertEqual(evalExpr([5,0, 1,1, 3,0, 1,2, 6,0, 3,2, 5,0, 1,3, 3,0, 1,4, 6,0]), 21);
});
test('eval: 2*3+4*5 = 26', () => {
  assertEqual(evalExpr([1,2, 3,2, 1,3, 3,0, 1,4, 3,2, 1,5]), 26);
});
test('eval: 1+2*3-4/2 = 5', () => {
  assertEqual(evalExpr([1,1, 3,0, 1,2, 3,2, 1,3, 3,1, 1,4, 3,3, 1,2]), 5);
});
test('eval: ((3+1)*2) = 8', () => {
  assertEqual(evalExpr([5,0, 5,0, 1,3, 3,0, 1,1, 6,0, 3,2, 1,2, 6,0]), 8);
});
test('eval: 단일 숫자 99', () => {
  assertEqual(evalExpr([1,99]), 99);
});
test('eval: 0+0 = 0', () => {
  assertEqual(evalExpr([1,0, 3,0, 1,0]), 0);
});
test('eval: 1000*1000 = 1000000', () => {
  assertEqual(evalExpr([1,1000, 3,2, 1,1000]), 1000000);
});

// ============================================================
// 3. 스택 VM 자체 호스팅 (selfhost_interp.fl8)
// ============================================================
console.log('\n── 스택 VM 자체 호스팅 ──');

const VM_SRC = loadFL8('selfhost_interp.fl8');

function runVM(prog: number[]): number[] {
  const progStr = '[' + prog.join(',') + ']';
  const src = VM_SRC + `\nrun_vm(${progStr})`;
  return runArr(src);
}

test('vm: PUSH/PRINT [42]', () => {
  assertEqual(runVM([0,42, 12, 14]), [42]);
});
test('vm: 3+4=7', () => {
  assertEqual(runVM([0,3, 0,4, 3, 12, 14]), [7]);
});
test('vm: x=10,y=5,x*y=50', () => {
  assertEqual(runVM([0,10, 2,0, 0,5, 2,1, 1,0, 1,1, 5, 12, 14]), [50]);
});
test('vm: if x<5 참 → [1]', () => {
  assertEqual(runVM([0,3, 2,0, 1,0, 0,5, 9, 8,14, 0,1, 12, 14]), [1]);
});
test('vm: if x<5 거짓 → []', () => {
  assertEqual(runVM([0,10, 2,0, 1,0, 0,5, 9, 8,14, 0,1, 12, 14]), []);
});
test('vm: sum(1..5)=15', () => {
  const prog = [
    0,0, 2,0, 0,1, 2,1,
    1,1, 0,5, 11, 8,19,
    1,0, 12, 14,
    1,0, 1,1, 3, 2,0,
    1,1, 0,1, 3, 2,1,
    7,8
  ];
  assertEqual(runVM(prog), [15]);
});
test('vm: NEG → -5', () => {
  assertEqual(runVM([0,5, 13, 12, 14]), [-5]);
});
test('vm: CMP_EQ 3==3 → 1', () => {
  assertEqual(runVM([0,3, 0,3, 10, 12, 14]), [1]);
});
test('vm: CMP_EQ 3==4 → 0', () => {
  assertEqual(runVM([0,3, 0,4, 10, 12, 14]), [0]);
});
test('vm: multi-print [1,2,3]', () => {
