  assertEqual(runVM([0,6, 2,0, 0,7, 2,1, 1,0, 1,1, 5, 2,2, 1,2, 12, 14]), [42]);
});
test('vm: (3+4)*6=42', () => {
  assertEqual(runVM([0,3, 0,4, 3, 0,6, 5, 12, 14]), [42]);
});
test('vm: if 5>0: 1 else 2 → [1]', () => {
  assertEqual(runVM([0,5, 2,0, 1,0, 0,0, 11,
                     8,15, 0,1, 7,17, 0,2, 12, 14]), [1]);
});
test('vm: if -1>0: 1 else 2 → [2]', () => {
