  const result = runNum(src);
  assertEqual(result, 40);
});

test('파이프라인: VM으로 팩토리얼(5!=120) 계산', () => {
  // n=5, result=1
  // loop: if n<=0 goto done
  //   result *= n, n -= 1, goto loop
  // done: print result
  //
  // var0=result, var1=n
  // [0]0,1  [2]2,0    result=1
  // [4]0,5  [6]2,1    n=5
  // loop(ip=8):
  // [8]1,1  [10]0,0  [12]11  CMP_GT(n>0?)
  // [13]8,[14]19      JMPF 19 (n<=0이면 done=ip19)
  // [15]1,0 [17]1,1 [18]5   result*=n
  // wait: MUL는 1칸, 그 전에 LOAD0,LOAD1
  // [15]1,[16]0  [17]1,[18]1  [19]5  [20]2,[21]0  result=result*n
  // [22]1,[23]1  [24]0,[25]1  [26]4  [27]2,[28]1  n=n-1
  // [29]7,[30]8  JMP 8
  // done(ip=31): [31]1,[32]0 [33]12 [34]14
  // JMPF → ip=31
  const prog = [
    0,1,  2,0,
    0,5,  2,1,
    1,1, 0,0, 11,
    8,31,
    1,0, 1,1, 5, 2,0,
    1,1, 0,1, 4, 2,1,
    7,8,
    1,0, 12, 14
  ];
  assertEqual(runVM(prog), [120]);
});

test('파이프라인: VM으로 피보나치(fib(8)=21)', () => {
  // a=0,b=1,n=8
  // loop: if n<=0 goto done
  //   tmp=a+b, a=b, b=tmp, n--
  // done: print a
  // var0=a, var1=b, var2=n, var3=tmp
  //
  // [0]0,0  [2]2,0    a=0
  // [4]0,1  [6]2,1    b=1
  // [8]0,8  [10]2,2   n=8
  // loop(ip=12):
  // [12]1,2 [14]0,0 [16]11  n>0?
  // [17]8,[18]37   JMPF 37 (done)
  // [19]1,0 [21]1,1 [22]3 [23]2,3  tmp=a+b
  // [25]1,1 [27]2,0  a=b
  // [29]1,3 [31]2,1  b=tmp
  // [33]1,2 [35]0,1 [36]4 [37]2,2  n=n-1
  // 아, [37]은 done이어야...
  // 재계산:
  // [33]1,[34]2  [35]0,[36]1  [37]4  [38]2,[39]2  n=n-1
  // [40]7,[41]12  JMP 12
  // done(ip=42): [42]1,[43]0 [44]12 [45]14
  // JMPF → 42
  const prog = [
    0,0, 2,0,
    0,1, 2,1,
    0,8, 2,2,
    1,2, 0,0, 11,
    8,42,
    1,0, 1,1, 3, 2,3,
    1,1, 2,0,
    1,3, 2,1,
    1,2, 0,1, 4, 2,2,
    7,12,
    1,0, 12, 14
  ];
  assertEqual(runVM(prog), [21]);
});

// ============================================================
console.log(`\n${'='.repeat(50)}`);
console.log(`Phase 10 결과: ${passed} PASS / ${failed} FAIL`);
if (failed > 0) process.exit(1);

