  // [25]1,1 [27]2,0  a=b
  // [29]1,3 [31]2,1  b=tmp
  // [33]1,2 [35]0,1 [36]4 [37]2,2  n=n-1
  // 아, [37]은 done이어야...
  // 재계산:
  // [33]1,[34]2  [35]0,[36]1  [37]4  [38]2,[39]2  n=n-1
