    8,42,
    1,0, 1,1, 3, 2,3,
    1,1, 2,0,
    1,3, 2,1,
    1,2, 0,1, 4, 2,2,
    7,12,
    1,0, 12, 14
  ];
  assertEqual(runVM(prog), [21]);
});

