package main

import (
	"fmt"
	"math"
	"math/rand"
	"os"
	"strings"
	"time"
)

// ==================================================
// Phase I: FreeLang GPT — 향상된 학습 파이프라인
//
// 개선사항:
//   - real_corpus.txt (FreeLang 소스/문서) 활용
//   - 더 큰 모델: d=256, heads=8, layers=6
//   - 더 긴 시퀀스: seqLen=64
//   - Top-K + Temperature 샘플링
//   - Perplexity 측정 + 텍스트 생성 샘플
//   - 체크포인트 저장 (최고 모델)
// ==================================================

// ─────────────────────────────────────────────────
// 코퍼스 로더 (real_corpus.txt)
// ─────────────────────────────────────────────────

type PhaseICorpus struct {
	tokens   []int
	vocab    map[string]int
	revVocab map[int]string
	vocabSize int
}

func loadPhaseICorpus(path string, maxChars int) (*PhaseICorpus, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("파일 읽기 실패: %w", err)
	}

	text := string(raw)
	if len(text) > maxChars {
		text = text[:maxChars]
	}

	// 단어 수준 토큰화 (공백/줄바꿈 기준)
	// FreeLang 코드 특성상 키워드가 중요하므로 단어 단위 사용
	words := strings.FieldsFunc(text, func(r rune) bool {
		return r == ' ' || r == '\t'
	})

	// vocab 구축
	freq := map[string]int{}
	for _, w := range words {
		freq[w]++
	}

	// 빈도순 정렬 (top 2000)
	type kv struct{ k string; v int }
	kvs := make([]kv, 0, len(freq))
	for k, v := range freq {
		kvs = append(kvs, kv{k, v})
	}
	// 간단한 삽입 정렬 (vocab 크기가 크지 않으므로)
	for i := 1; i < len(kvs); i++ {
		j := i
		for j > 0 && kvs[j-1].v < kvs[j].v {
			kvs[j-1], kvs[j] = kvs[j], kvs[j-1]
			j--
		}
	}

	maxVocab := 2000
	if len(kvs) < maxVocab {
		maxVocab = len(kvs)
	}

	vocab := map[string]int{"<PAD>": 0, "<UNK>": 1, "<BOS>": 2, "<EOS>": 3}
	revVocab := map[int]string{0: "<PAD>", 1: "<UNK>", 2: "<BOS>", 3: "<EOS>"}
	nextID := 4

	for _, item := range kvs[:maxVocab] {
		if _, ok := vocab[item.k]; !ok {
			vocab[item.k] = nextID
			revVocab[nextID] = item.k
			nextID++
		}
	}

	// 토큰화
	tokens := make([]int, 0, len(words))
	for _, w := range words {
		if id, ok := vocab[w]; ok {
			tokens = append(tokens, id)
		} else {
			tokens = append(tokens, 1) // <UNK>
		}
	}

	return &PhaseICorpus{
		tokens:    tokens,
		vocab:     vocab,
		revVocab:  revVocab,
		vocabSize: len(vocab),
	}, nil
}

// ─────────────────────────────────────────────────
// Top-K Temperature 샘플링
// ─────────────────────────────────────────────────

func topKSample(logits []float64, k int, temperature float64) int {
	if temperature <= 0 {
		temperature = 1.0
	}

	n := len(logits)
	if k <= 0 || k > n {
		k = n
	}

	// Temperature 스케일링
	scaled := make([]float64, n)
	for i, v := range logits {
		scaled[i] = v / temperature
	}

	// Softmax
	probs := softmax1D(scaled)

	// Top-K 선택
	type idxVal struct{ idx int; val float64 }
	topK := make([]idxVal, n)
	for i, v := range probs {
		topK[i] = idxVal{i, v}
	}
	// 내림차순 정렬 (삽입정렬, k가 작으므로 충분)
	for i := 1; i < n; i++ {
		j := i
		for j > 0 && topK[j-1].val < topK[j].val {
			topK[j-1], topK[j] = topK[j], topK[j-1]
			j--
		}
	}

	// Top-K 재정규화
	total := 0.0
	for i := 0; i < k; i++ {
		total += topK[i].val
	}
	if total == 0 {
		return topK[0].idx
	}

	// 확률적 선택
	r := rand.Float64() * total
	cumul := 0.0
	for i := 0; i < k; i++ {
		cumul += topK[i].val
		if r <= cumul {
			return topK[i].idx
		}
	}
	return topK[0].idx
}

// ─────────────────────────────────────────────────
// 텍스트 생성
// ─────────────────────────────────────────────────

func generatePhaseI(model *NLayerModel, corpus *PhaseICorpus, prompt string, maxTokens int, temperature float64, topK int) string {
	// 프롬프트 토큰화
	words := strings.Fields(prompt)
	seq := make([]int, 0, len(words)+maxTokens)
	for _, w := range words {
		if id, ok := corpus.vocab[w]; ok {
			seq = append(seq, id)
		} else {
			seq = append(seq, 1) // <UNK>
		}
	}
	if len(seq) == 0 {
		seq = append(seq, 2) // <BOS>
	}

	generated := make([]string, 0, maxTokens)

	for i := 0; i < maxTokens; i++ {
		// 컨텍스트 윈도우 제한
		ctx := seq
		if len(ctx) > 64 {
			ctx = ctx[len(ctx)-64:]
		}

		logits, _ := model.forwardNL(ctx)
		nextID := topKSample(logits, topK, temperature)

		if nextID == 3 { // <EOS>
			break
		}

		seq = append(seq, nextID)
		if tok, ok := corpus.revVocab[nextID]; ok {
			generated = append(generated, tok)
		}
	}

	return strings.Join(generated, " ")
}

// ─────────────────────────────────────────────────
// Perplexity 계산 (검증 셋)
// ─────────────────────────────────────────────────

func calcPerplexity(model *NLayerModel, tokens []int, seqLen, numSamples int) float64 {
	if len(tokens) <= seqLen+1 {
		return math.Exp(10)
	}

	totalLoss := 0.0
	count := 0

	for i := 0; i < numSamples; i++ {
		start := rand.Intn(len(tokens) - seqLen - 1)
		seq := tokens[start : start+seqLen]
		target := tokens[start+seqLen]

		logits, _ := model.forwardNL(seq)
		probs := softmax1D(logits)
		loss := -math.Log(probs[target] + 1e-10)
		totalLoss += loss
		count++
	}

	if count == 0 {
		return math.Exp(10)
	}
	return math.Exp(totalLoss / float64(count))
}

// ─────────────────────────────────────────────────
// Phase I 학습 메인
// ─────────────────────────────────────────────────

func trainPhaseI() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
