			}

			// Backward
			model.backwardNL(
				seq, target, fwd, dLogits,
				optim.blocks, optim.proj, optim.emb,
				optim.lnFScale, optim.lnFBias,
			)
		}

		avgLoss := epochLoss / float64(batchPerEpoch)
		ppl     := math.Exp(avgLoss)

		// 검증 Perplexity
		valPPL := calcPerplexity(model, valTokens, seqLen, 50)

		mark := ""
		if valPPL < bestPPL {
			bestPPL = valPPL
			mark = " ★ best"
			// 최고 모델 바이너리 캡처
			tmpPath := "data/phase_i_best.bin"
			if err2 := saveNLModel(model, tmpPath); err2 == nil {
				bestModelData, _ = os.ReadFile(tmpPath)
			}
		}

		elapsed := time.Since(startTime).Seconds()
		fmt.Printf("✅ Epoch %02d/%d | loss=%.4f PPL=%.2f | valPPL=%.2f%s | %.0fs\n",
			epoch, epochs, avgLoss, ppl, valPPL, mark, elapsed)

		// 5 에포크마다 텍스트 생성 샘플
		if epoch%5 == 0 {
			sample := generatePhaseI(model, corpus, "fn", 15, 0.8, 5)
			fmt.Printf("   💬 샘플: fn %s\n", sample)
		}
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")

	// 5. 최고 모델 복원 및 저장
	fmt.Println("[4/5] 최고 모델 저장...")
	savePath := "data/phase_i_model.bin"

	if bestModelData != nil {
		if err2 := os.WriteFile(savePath, bestModelData, 0644); err2 != nil {
			fmt.Printf("⚠️  최고 모델 저장 실패: %v\n", err2)
		} else {
			fmt.Printf("✅ 최고 모델 저장: %s (valPPL=%.2f)\n", savePath, bestPPL)
		}
		// 임시 파일 정리
		os.Remove("data/phase_i_best.bin")
	} else {
		// 현재 모델 저장
		if err2 := saveNLModel(model, savePath); err2 != nil {
			fmt.Printf("⚠️  모델 저장 실패: %v\n", err2)
		} else {
			fmt.Printf("✅ 현재 모델 저장: %s\n", savePath)
		}
	}

	// 6. 텍스트 생성 데모
	fmt.Println("\n[5/5] 텍스트 생성 데모...")
	prompts := []string{"fn", "let", "//", "FreeLang"}
	temps   := []float64{0.7, 1.0, 1.2}
	topKs   := []int{5, 10}

	for _, prompt := range prompts {
		fmt.Printf("\n📝 프롬프트: \"%s\"\n", prompt)
		for _, temp := range temps[:2] {
			sample := generatePhaseI(model, corpus, prompt, 20, temp, topKs[0])
			fmt.Printf("   temp=%.1f: %s %s\n", temp, prompt, sample)
		}
	}

	// 최종 요약
	fmt.Printf("\n╔══════════════════════════════════════════════════════════════╗\n")
	fmt.Printf("║  Phase I 완료                                              ║\n")
	fmt.Printf("║  Best Val PPL: %.2f                                       ║\n", bestPPL)
	fmt.Printf("║  모델: %s                                    ║\n", savePath)
	fmt.Printf("╚══════════════════════════════════════════════════════════════╝\n")
}

