	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(data) == 0 {
		return nil, fmt.Errorf("모델 파일이 비어 있습니다")
	}
	_ = data
	// NLayerModel은 saveNLModel/loadNLModel이 이미 transformer_nlayer.go에 있음
	// 여기서는 해당 함수를 그대로 위임
	return loadNLModelFromFile(path)
}

// ─────────────────────────────────────────────────
// Fluency 점수: 생성된 텍스트의 단어 다양성
// ─────────────────────────────────────────────────

func fluencyScore(samples []GeneratedSample) float64 {
	allWords := map[string]bool{}
	total := 0
	for _, s := range samples {
		words := strings.Fields(s.Text)
		for _, w := range words {
			allWords[w] = true
			total++
		}
	}
	if total == 0 {
		return 0
	}
	return float64(len(allWords)) / float64(total)
}

