// ─────────────────────────────────────────────────
// Fluency 점수: 생성된 텍스트의 단어 다양성
// ─────────────────────────────────────────────────

func fluencyScore(samples []GeneratedSample) float64 {
	allWords := map[string]bool{}
	total := 0
	for _, s := range samples {
		words := strings.Fields(s.Text)
		for _, w := range words {
			allWords[w] = true
			total++
		}
	}
	if total == 0 {
		return 0
	}
	return float64(len(allWords)) / float64(total)
}

