func handlePhaseISample(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	prompts := []string{"fn", "let", "//", "return", "FreeLang"}
	prompt := prompts[rand.Intn(len(prompts))]

