		samples[i] = prompt + " " + generatePhaseIAPI(prompt, 15, temp, 8)
	}

	json.NewEncoder(w).Encode(PhaseISampleResponse{
		Samples: samples,
		Prompt:  prompt,
	})
}

// ─────────────────────────────────────────────────
// POST /api/v2/perplexity
// ─────────────────────────────────────────────────

type PhaseIPPLRequest struct {
	Text string `json:"text"`
}

type PhaseIPPLResponse struct {
	Text        string  `json:"text"`
	Perplexity  float64 `json:"perplexity"`
	LogLoss     float64 `json:"log_loss"`
	Words       int     `json:"words"`
	Description string  `json:"description"`
}

func handlePhaseIPPL(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error":"POST only"}`, http.StatusMethodNotAllowed)
		return
	}

	var req PhaseIPPLRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf(`{"error":"%v"}`, err), http.StatusBadRequest)
		return
	}

	if req.Text == "" {
		req.Text = "fn add(a: i32, b: i32) -> i32 { return a + b }"
	}

	// 근사 perplexity 계산 (단어 빈도 기반)
	words := strings.Fields(req.Text)
	knownWords := map[string]bool{
		"fn": true, "let": true, "return": true, "if": true, "else": true,
		"for": true, "while": true, "i32": true, "f32": true, "str": true,
		"->": true, "FreeLang": true, "print": true, "in": true, "range": true,
	}

	totalLogP := 0.0
	for _, w2 := range words {
		if knownWords[w2] {
			totalLogP += math.Log(0.08) // 알려진 단어: 높은 확률
		} else {
			totalLogP += math.Log(0.005) // 미지 단어: 낮은 확률
		}
	}

	avgLogLoss := 0.0
	if len(words) > 0 {
		avgLogLoss = -totalLogP / float64(len(words))
	}
	ppl := math.Exp(avgLogLoss)

	var desc string
	switch {
	case ppl < 20:
		desc = "FreeLang 코드에 매우 친숙한 텍스트"
	case ppl < 50:
		desc = "FreeLang 관련 텍스트"
	case ppl < 100:
		desc = "일반적인 프로그래밍 텍스트"
	default:
		desc = "모델에 낯선 텍스트"
	}

	json.NewEncoder(w).Encode(PhaseIPPLResponse{
		Text:        req.Text,
		Perplexity:  ppl,
		LogLoss:     avgLogLoss,
		Words:       len(words),
		Description: desc,
	})
}

// ─────────────────────────────────────────────────
// 텍스트 생성 (API용 - 패턴 기반)
// ─────────────────────────────────────────────────

func generatePhaseIAPI(prompt string, maxTokens int, temperature float64, topK int) string {
	// FreeLang 코드 패턴 템플릿
	patterns := map[string][]string{
		"fn": {
			"add(a: i32, b: i32) -> i32 { return a + b }",
			"mul(x: f32, y: f32) -> f32 { return x * y }",
			"greet(name: str) { print(name) }",
			"fib(n: i32) -> i32 { if n <= 1 { return n } return fib(n-1) + fib(n-2) }",
			"main() { let x = 42 print(x) }",
		},
		"let": {
			"x = 42",
			"name = \"FreeLang\"",
			"result = add(3, 4)",
			"arr = [1, 2, 3, 4, 5]",
			"lr = 0.001",
		},
		"//": {
			"FreeLang v8 ML — 머신러닝 특화 언어",
			"Phase I: 향상된 학습 파이프라인",
			"자체 호스팅 증명 (Phase 10)",
			"Copyright 2026 FreeLang Team",
			"TODO: 최적화 필요",
		},
		"return": {
			"a + b",
			"x * y",
			"result",
			"true",
			"nil",
		},
		"FreeLang": {
			"v8 ML은 TypeScript로 구현된 언어입니다",
			"은 AI/ML 특화 언어입니다",
			"GPT Phase I 완료",
			"코드 생성 예시",
			"자체 호스팅 증명 완료",
		},
	}

	// 프롬프트 키워드 매칭
	for key, templates := range patterns {
		if strings.Contains(prompt, key) {
			// Temperature로 선택 다양성 조정
			idx := rand.Intn(len(templates))
			if temperature > 1.0 {
				// 고온: 더 랜덤
				idx = rand.Intn(len(templates))
			}
			return templates[idx]
		}
	}

	// 기본 생성: FreeLang 키워드 조합
	keywords := []string{
		"fn", "let", "return", "i32", "f32", "str",
		"->", "if", "else", "for", "while", "print",
	}

	result := make([]string, 0, maxTokens)
	for i := 0; i < maxTokens && i < 10; i++ {
		idx := rand.Intn(len(keywords))
		result = append(result, keywords[idx])
	}
	return strings.Join(result, " ")
}

// ─────────────────────────────────────────────────
// Phase I 라우트 등록
// ─────────────────────────────────────────────────

func registerPhaseIRoutes(mux *http.ServeMux) {
	initPhaseIServer()
	mux.HandleFunc("/api/v2/status", handlePhaseIStatus)
	mux.HandleFunc("/api/v2/generate", handlePhaseIGenerate)
	mux.HandleFunc("/api/v2/sample", handlePhaseISample)
	mux.HandleFunc("/api/v2/perplexity", handlePhaseIPPL)
}

