	expectedWords := []string{"fn", "add(a:", "i32,", "b:", "i32)", "->", "i32", "{", "return", "a", "+", "b", "}"}
	if len(words) != len(expectedWords) {
		t.Errorf("단어 수: got %d want %d", len(words), len(expectedWords))
	}

	// vocab 구축 테스트
	vocab := map[string]int{"<PAD>": 0, "<UNK>": 1, "<BOS>": 2, "<EOS>": 3}
	for i, w := range words {
		vocab[w] = 4 + i
	}

	// 토큰 인코딩
	tokens := make([]int, len(words))
	for i, w := range words {
		if id, ok := vocab[w]; ok {
			tokens[i] = id
		} else {
			tokens[i] = 1 // <UNK>
		}
	}

	if len(tokens) == 0 {
		t.Error("토큰 생성 실패")
	}
	for _, tok := range tokens {
		if tok < 0 {
			t.Errorf("음수 토큰: %d", tok)
		}
	}
	t.Logf("토큰화 결과: %d 단어 → %d 토큰", len(words), len(tokens))
}

// ─────────────────────────────────────────────────
// 통합 테스트: 생성 다양성 (temperature 효과)
// ─────────────────────────────────────────────────

func TestGenerationDiversity(t *testing.T) {
	prompt := "fn"
	maxTokens := 5

	// 낮은 temperature: 결정론적
	low1 := generateAPIResult(prompt, maxTokens, 0.1, 2)
	low2 := generateAPIResult(prompt, maxTokens, 0.1, 2)

	// 두 번 모두 같은 결과여야 함 (결정론적 패턴)
	if low1 == "" || low2 == "" {
		t.Error("생성 결과가 비어 있음")
	}
	t.Logf("low temp: '%s' vs '%s'", low1, low2)

	// 높은 temperature: 결과 비어 있지 않아야 함
	high := generateAPIResult(prompt, maxTokens, 1.5, 10)
	if high == "" {
		t.Error("high temp 생성 결과가 비어 있음")
	}
	t.Logf("high temp: '%s'", high)
}

// ─────────────────────────────────────────────────
// 통합 테스트: 에러 케이스
// ─────────────────────────────────────────────────

func TestGenerateEdgeCases(t *testing.T) {
	// 빈 프롬프트
	result := generateAPIResult("", 10, 0.8, 5)
	if result == "" {
		t.Error("빈 프롬프트에서도 결과 있어야 함")
	}

	// 매우 긴 프롬프트
	longPrompt := strings.Repeat("fn ", 100)
	result2 := generateAPIResult(longPrompt, 5, 0.8, 5)
	if result2 == "" {
		t.Error("긴 프롬프트에서도 결과 있어야 함")
	}

	// topK=1 (greedy)
	result3 := generateAPIResult("let", 5, 1.0, 1)
	if result3 == "" {
		t.Error("topK=1에서도 결과 있어야 함")
	}
}

