		j := i
		for j > 0 && topK[j-1].val < topK[j].val {
			topK[j-1], topK[j] = topK[j], topK[j-1]
			j--
		}
	}

	// Top-K 재정규화
	total := 0.0
	for i := 0; i < k; i++ {
		total += topK[i].val
	}
	if total == 0 {
		return topK[0].idx
	}

	// 확률적 선택
	r := rand.Float64() * total
	cumul := 0.0
	for i := 0; i < k; i++ {
		cumul += topK[i].val
		if r <= cumul {
			return topK[i].idx
		}
	}
	return topK[0].idx
}

// ─────────────────────────────────────────────────
// 텍스트 생성
// ─────────────────────────────────────────────────

func generatePhaseI(model *NLayerModel, corpus *PhaseICorpus, prompt string, maxTokens int, temperature float64, topK int) string {
	// 프롬프트 토큰화
	words := strings.Fields(prompt)
	seq := make([]int, 0, len(words)+maxTokens)
	for _, w := range words {
		if id, ok := corpus.vocab[w]; ok {
			seq = append(seq, id)
		} else {
			seq = append(seq, 1) // <UNK>
		}
	}
	if len(seq) == 0 {
		seq = append(seq, 2) // <BOS>
	}

	generated := make([]string, 0, maxTokens)

	for i := 0; i < maxTokens; i++ {
		// 컨텍스트 윈도우 제한
		ctx := seq
		if len(ctx) > 64 {
			ctx = ctx[len(ctx)-64:]
		}

		logits, _ := model.forwardNL(ctx)
		nextID := topKSample(logits, topK, temperature)

		if nextID == 3 { // <EOS>
			break
		}

		seq = append(seq, nextID)
		if tok, ok := corpus.revVocab[nextID]; ok {
			generated = append(generated, tok)
		}
	}

	return strings.Join(generated, " ")
}

// ─────────────────────────────────────────────────
// Perplexity 계산 (검증 셋)
// ─────────────────────────────────────────────────

func calcPerplexity(model *NLayerModel, tokens []int, seqLen, numSamples int) float64 {
	if len(tokens) <= seqLen+1 {
		return math.Exp(10)
	}

	totalLoss := 0.0
	count := 0

	for i := 0; i < numSamples; i++ {
		start := rand.Intn(len(tokens) - seqLen - 1)
		seq := tokens[start : start+seqLen]
		target := tokens[start+seqLen]

		logits, _ := model.forwardNL(seq)
		probs := softmax1D(logits)
		loss := -math.Log(probs[target] + 1e-10)
		totalLoss += loss
		count++
	}

	if count == 0 {
		return math.Exp(10)
	}
	return math.Exp(totalLoss / float64(count))
}

// ─────────────────────────────────────────────────
// Phase I 학습 메인
// ─────────────────────────────────────────────────

func trainPhaseI() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT — Phase I: 향상된 학습 파이프라인             ║")
	fmt.Println("║  실제 FreeLang corpus + 더 큰 모델 + Top-K 샘플링          ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 1. 코퍼스 로드
	fmt.Println("[1/5] 코퍼스 로드 중...")
	corpus, err := loadPhaseICorpus("data/real_corpus.txt", 500_000)
	if err != nil {
		// fallback: real_corpus_large.txt
		corpus, err = loadPhaseICorpus("data/real_corpus_large.txt", 300_000)
		if err != nil {
			fmt.Printf("❌ corpus 로드 실패: %v\n", err)
			return
		}
	}

	fmt.Printf("✅ vocab=%d, tokens=%d\n\n", corpus.vocabSize, len(corpus.tokens))

	// 2. 모델 생성
	fmt.Println("[2/5] 모델 초기화...")
	d       := 128
	ffn     := 512
	numHeads := 4
	numLayers := 4

	model := newNLayerModel(corpus.vocabSize, d, ffn, numHeads, numLayers)
	optim := newNLayerOptim(0.0003, corpus.vocabSize, d, ffn, numLayers)

	params := corpus.vocabSize*d + numLayers*(4*d*d+2*d*ffn) + d*corpus.vocabSize
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, layers=%d, params=~%dk\n\n",
		d, numHeads, ffn, numLayers, params/1000)

	// 3. 학습 설정
	epochs        := 20
	batchPerEpoch := 300
	seqLen        := 32
	warmup        := epochs * batchPerEpoch / 10
	total         := epochs * batchPerEpoch
	bestPPL       := math.MaxFloat64
	bestModelData := []byte(nil)
	step          := 0

	// 검증 셋 (끝 10%)
	splitIdx := len(corpus.tokens) * 9 / 10
	trainTokens := corpus.tokens[:splitIdx]
	valTokens   := corpus.tokens[splitIdx:]

	fmt.Printf("학습 토큰: %d, 검증 토큰: %d\n", len(trainTokens), len(valTokens))
	fmt.Printf("seqLen=%d, epochs=%d, batches/epoch=%d, warmup=%d\n\n",
		seqLen, epochs, batchPerEpoch, warmup)
	fmt.Println("══════════════════════════════════════════════════════════════")

	// 4. 학습 루프
	fmt.Println("[3/5] 학습 시작...")
	startTime := time.Now()

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < batchPerEpoch; batch++ {
			step++
			if len(trainTokens) <= seqLen+1 {
				break
			}
			start  := rand.Intn(len(trainTokens) - seqLen - 1)
			seq    := trainTokens[start : start+seqLen]
			target := trainTokens[start+seqLen]

			// LR warmup + cosine decay
			lr := 0.0003
			if step <= warmup {
				lr = 0.0003 * float64(step) / float64(warmup)
			} else {
				p := float64(step-warmup) / float64(total-warmup)
				lr = 0.0003 * 0.5 * (1 + math.Cos(math.Pi*p))
			}
			if lr < 1e-6 {
				lr = 1e-6
			}
			optim.setLR(lr)

			// Forward
			logits, fwd := model.forwardNL(seq)
			probs := softmax1D(logits)
			loss  := -math.Log(probs[target] + 1e-10)
			epochLoss += loss

			// dLogits (softmax cross-entropy gradient)
			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if target < len(dLogits) {
				dLogits[target] -= 1.0
			}

			// Backward
			model.backwardNL(
				seq, target, fwd, dLogits,
				optim.blocks, optim.proj, optim.emb,
				optim.lnFScale, optim.lnFBias,
			)
		}

		avgLoss := epochLoss / float64(batchPerEpoch)
		ppl     := math.Exp(avgLoss)

		// 검증 Perplexity
		valPPL := calcPerplexity(model, valTokens, seqLen, 50)

		mark := ""
		if valPPL < bestPPL {
			bestPPL = valPPL
			mark = " ★ best"
			// 최고 모델 바이너리 캡처
			tmpPath := "data/phase_i_best.bin"
			if err2 := saveNLModel(model, tmpPath); err2 == nil {
				bestModelData, _ = os.ReadFile(tmpPath)
			}
		}

		elapsed := time.Since(startTime).Seconds()
		fmt.Printf("✅ Epoch %02d/%d | loss=%.4f PPL=%.2f | valPPL=%.2f%s | %.0fs\n",
			epoch, epochs, avgLoss, ppl, valPPL, mark, elapsed)

		// 5 에포크마다 텍스트 생성 샘플
		if epoch%5 == 0 {
			sample := generatePhaseI(model, corpus, "fn", 15, 0.8, 5)
			fmt.Printf("   💬 샘플: fn %s\n", sample)
		}
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")

	// 5. 최고 모델 복원 및 저장
	fmt.Println("[4/5] 최고 모델 저장...")
	savePath := "data/phase_i_model.bin"

	if bestModelData != nil {
		if err2 := os.WriteFile(savePath, bestModelData, 0644); err2 != nil {
			fmt.Printf("⚠️  최고 모델 저장 실패: %v\n", err2)
		} else {
			fmt.Printf("✅ 최고 모델 저장: %s (valPPL=%.2f)\n", savePath, bestPPL)
		}
		// 임시 파일 정리
		os.Remove("data/phase_i_best.bin")
	} else {
		// 현재 모델 저장
		if err2 := saveNLModel(model, savePath); err2 != nil {
			fmt.Printf("⚠️  모델 저장 실패: %v\n", err2)
		} else {
			fmt.Printf("✅ 현재 모델 저장: %s\n", savePath)
		}
	}

	// 6. 텍스트 생성 데모
	fmt.Println("\n[5/5] 텍스트 생성 데모...")
	prompts := []string{"fn", "let", "//", "FreeLang"}
	temps   := []float64{0.7, 1.0, 1.2}
	topKs   := []int{5, 10}

	for _, prompt := range prompts {
		fmt.Printf("\n📝 프롬프트: \"%s\"\n", prompt)
		for _, temp := range temps[:2] {
			sample := generatePhaseI(model, corpus, prompt, 20, temp, topKs[0])
			fmt.Printf("   temp=%.1f: %s %s\n", temp, prompt, sample)
		}
	}

	// 최종 요약
	fmt.Printf("\n╔══════════════════════════════════════════════════════════════╗\n")
	fmt.Printf("║  Phase I 완료                                              ║\n")
	fmt.Printf("║  Best Val PPL: %.2f                                       ║\n", bestPPL)
	fmt.Printf("║  모델: %s                                    ║\n", savePath)
	fmt.Printf("╚══════════════════════════════════════════════════════════════╝\n")
}

package main

import (
	"fmt"
	"os"
	"strings"
)

// ==================================================
// Phase I: 평가 모듈
//
// - loadPhaseIModel: 저장된 Phase I 모델 로드
// - evalPhaseI: vocab + 모델 로드 후 평가
// - PhaseIResult: 평가 결과 구조체
// ==================================================

// 평가 결과
type PhaseIResult struct {
	ValPPL    float64
	Samples   []GeneratedSample
	VocabSize int
	Params    int
}

type GeneratedSample struct {
	Prompt   string
	Text     string
	Temp     float64
	TopK     int
}

// ─────────────────────────────────────────────────
// evalPhaseI: 저장된 모델 로드 후 평가
// ─────────────────────────────────────────────────

func evalPhaseI() *PhaseIResult {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT — Phase I: 모델 평가                         ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 코퍼스 로드
	fmt.Print("[1/3] 코퍼스 로드... ")
	corpus, err := loadPhaseICorpus("data/real_corpus.txt", 500_000)
	if err != nil {
		corpus, err = loadPhaseICorpus("data/real_corpus_large.txt", 300_000)
		if err != nil {
			fmt.Printf("❌ %v\n", err)
			return nil
		}
	}
	fmt.Printf("✅ vocab=%d tokens=%d\n", corpus.vocabSize, len(corpus.tokens))

	// 모델 로드
	fmt.Print("[2/3] 모델 로드... ")
	modelPath := "data/phase_i_model.bin"
	if _, err2 := os.Stat(modelPath); os.IsNotExist(err2) {
		fmt.Printf("❌ %s 없음 (먼저 phase_i 실행)\n", modelPath)
		return nil
	}

	model, err := loadNLModel(modelPath)
	if err != nil {
		fmt.Printf("❌ %v\n", err)
		return nil
	}
	fmt.Printf("✅ d=%d layers=%d\n", model.dModel, model.numLayers)

	// Perplexity 계산
	fmt.Print("[3/3] Perplexity 계산... ")
	splitIdx    := len(corpus.tokens) * 9 / 10
	valTokens   := corpus.tokens[splitIdx:]
	valPPL      := calcPerplexity(model, valTokens, 32, 200)
	fmt.Printf("✅ valPPL=%.2f\n\n", valPPL)

	// 텍스트 생성
	fmt.Println("═══ 텍스트 생성 평가 ═══════════════════════════════════════════")
	samples := []GeneratedSample{}

	testCases := []struct {
		prompt string
		temp   float64
		topK   int
	}{
		{"fn", 0.7, 5},
		{"fn", 1.0, 10},
		{"let", 0.7, 5},
		{"let", 1.0, 10},
		{"//", 0.8, 8},
		{"FreeLang", 0.7, 5},
		{"Phase", 0.9, 8},
		{"return", 0.7, 5},
	}

	for _, tc := range testCases {
		text := generatePhaseI(model, corpus, tc.prompt, 20, tc.temp, tc.topK)
		samples = append(samples, GeneratedSample{
			Prompt: tc.prompt,
			Text:   text,
			Temp:   tc.temp,
			TopK:   tc.topK,
		})
		fmt.Printf("  \"%s\" (t=%.1f k=%d): %s %s\n",
			tc.prompt, tc.temp, tc.topK, tc.prompt, text)
	}

	params := model.vocabSize*model.dModel +
		model.numLayers*(4*model.dModel*model.dModel+2*model.dModel*model.dFFn) +
		model.dModel*model.vocabSize

	result := &PhaseIResult{
		ValPPL:    valPPL,
		Samples:   samples,
		VocabSize: corpus.vocabSize,
		Params:    params,
	}

	// 요약
	fmt.Printf("\n╔══════════════════════════════════════════════════════════════╗\n")
	fmt.Printf("║  평가 결과 요약                                             ║\n")
	fmt.Printf("║  ValPPL:   %.2f                                           ║\n", valPPL)
	fmt.Printf("║  VocabSize: %d                                           ║\n", corpus.vocabSize)
	fmt.Printf("║  Params:   ~%dk                                          ║\n", params/1000)
	fmt.Printf("╚══════════════════════════════════════════════════════════════╝\n")

	return result
}


// ─────────────────────────────────────────────────
// Fluency 점수: 생성된 텍스트의 단어 다양성
// ─────────────────────────────────────────────────

func fluencyScore(samples []GeneratedSample) float64 {
	allWords := map[string]bool{}
	total := 0
	for _, s := range samples {
		words := strings.Fields(s.Text)
		for _, w := range words {
			allWords[w] = true
			total++
		}
	}
	if total == 0 {
		return 0
	}
	return float64(len(allWords)) / float64(total)
}

// ─────────────────────────────────────────────────
// evalPhaseIReport: 텍스트 보고서 생성
// ─────────────────────────────────────────────────

func evalPhaseIReport(r *PhaseIResult) string {
	if r == nil {
		return "평가 실패"
	}

	var sb strings.Builder
	sb.WriteString("# FreeLang GPT Phase I — 평가 보고서\n\n")
	sb.WriteString(fmt.Sprintf("- 검증 Perplexity: **%.2f**\n", r.ValPPL))
	sb.WriteString(fmt.Sprintf("- 어휘 크기: %d\n", r.VocabSize))
	sb.WriteString(fmt.Sprintf("- 파라미터: ~%dk\n", r.Params/1000))

	fluency := fluencyScore(r.Samples)
	sb.WriteString(fmt.Sprintf("- 유창성 점수: %.3f\n\n", fluency))

	sb.WriteString("## 생성 샘플\n\n")
	for _, s := range r.Samples {
		sb.WriteString(fmt.Sprintf("**`%s`** (temp=%.1f, k=%d): %s %s\n\n",
			s.Prompt, s.Temp, s.TopK, s.Prompt, s.Text))
	}

	// 등급 판정
	grade := "F"
	switch {
	case r.ValPPL < 50:
		grade = "A"
	case r.ValPPL < 100:
		grade = "B"
	case r.ValPPL < 200:
		grade = "C"
	case r.ValPPL < 500:
		grade = "D"
	default:
		grade = "F"
	}

	sb.WriteString(fmt.Sprintf("\n## 종합 등급: **%s** (PPL=%.2f)\n", grade, r.ValPPL))
	return sb.String()
}

// ─────────────────────────────────────────────────
// NLayerModel 파일 로드 (transformer_nlayer.go에 있는 함수 위임)
// ─────────────────────────────────────────────────

func loadNLModelFromFile(path string) (*NLayerModel, error) {
	return loadNLModel(path)
}

// ─────────────────────────────────────────────────
// 토큰 시퀀스 → 텍스트 (디코딩)
// ─────────────────────────────────────────────────

func decodeTokens(tokens []int, revVocab map[int]string) string {
	words := make([]string, 0, len(tokens))
	for _, id := range tokens {
		if w, ok := revVocab[id]; ok {
			words = append(words, w)
		} else {
			words = append(words, "<UNK>")
		}
	}
	return strings.Join(words, " ")
}

// ─────────────────────────────────────────────────
// 비교 평가: nl_model.bin (Phase 8) vs phase_i_model.bin
// ─────────────────────────────────────────────────

func compareModels() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  모델 비교: Phase 8 vs Phase I                              ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	corpus, err := loadPhaseICorpus("data/real_corpus.txt", 200_000)
	if err != nil {
		corpus, err = loadPhaseICorpus("data/real_corpus_large.txt", 200_000)
		if err != nil {
			fmt.Printf("❌ corpus: %v\n", err)
			return
		}
	}

	splitIdx  := len(corpus.tokens) * 9 / 10
	valTokens := corpus.tokens[splitIdx:]

	models := []struct {
		name string
		path string
	}{
		{"Phase 8", "data/nl_model.bin"},
		{"Phase I", "data/phase_i_model.bin"},
	}

	fmt.Printf("%-10s %10s %12s\n", "모델", "ValPPL", "파라미터")
	fmt.Println(strings.Repeat("─", 35))

	for _, m := range models {
		if _, err2 := os.Stat(m.path); os.IsNotExist(err2) {
			fmt.Printf("%-10s %10s\n", m.name, "N/A")
			continue
		}
		model, err2 := loadNLModelFromFile(m.path)
		if err2 != nil {
			fmt.Printf("%-10s %10s (%v)\n", m.name, "ERR", err2)
			continue
		}
		valPPL := calcPerplexity(model, valTokens, 32, 100)
		params := model.vocabSize*model.dModel +
			model.numLayers*(4*model.dModel*model.dModel+2*model.dModel*model.dFFn) +
			model.dModel*model.vocabSize
		fmt.Printf("%-10s %10.2f %12dk\n", m.name, valPPL, params/1000)
	}

	// Perplexity 개선률 계산
	fmt.Println()
	if _, err2 := os.Stat("data/nl_model.bin"); !os.IsNotExist(err2) {
		if _, err3 := os.Stat("data/phase_i_model.bin"); !os.IsNotExist(err3) {
			m8, e8 := loadNLModelFromFile("data/nl_model.bin")
			mi, ei := loadNLModelFromFile("data/phase_i_model.bin")
			if e8 == nil && ei == nil {
				ppl8 := calcPerplexity(m8, valTokens, 32, 100)
				pplI := calcPerplexity(mi, valTokens, 32, 100)
				impr := (ppl8 - pplI) / ppl8 * 100
				if impr > 0 {
					fmt.Printf("✅ Phase I 개선: %.1f%% (%.2f → %.2f)\n", impr, ppl8, pplI)
				} else {
					fmt.Printf("⚠️  Phase 8이 더 낮음: %.2f vs %.2f\n", ppl8, pplI)
				}
			}
		}
	}

}

