func (t *BPETokenizer) VocabSize() int {
	return len(t.Vocab)
}

// ─────────────────────────────────────────────────
// 저장 / 로드
// ─────────────────────────────────────────────────

func (t *BPETokenizer) Save(path string) error {
	mergesRaw := make([][]string, len(t.Merges))
	for i, m := range t.Merges {
		mergesRaw[i] = []string{m.A, m.B}
	}
	cfg := BPEConfig{Vocab: t.Vocab, Merges: mergesRaw}
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil { return err }
	return os.WriteFile(path, data, 0644)
}

func LoadBPETokenizer(path string) (*BPETokenizer, error) {
	data, err := os.ReadFile(path)
	if err != nil { return nil, err }
	var cfg BPEConfig
	if err := json.Unmarshal(data, &cfg); err != nil { return nil, err }

	merges := make([]BPEMerge, len(cfg.Merges))
	for i, m := range cfg.Merges {
		merges[i] = BPEMerge{m[0], m[1], m[0] + m[1]}
	}
	rev := make(map[int]string, len(cfg.Vocab))
	for k, v := range cfg.Vocab { rev[v] = k }

	return &BPETokenizer{Vocab: cfg.Vocab, RevVocab: rev, Merges: merges}, nil
}

// ─────────────────────────────────────────────────
// 내부 헬퍼
// ─────────────────────────────────────────────────

func tokenizeWords(text string) []string {
	// 공백/개행으로 분리
	return strings.FieldsFunc(text, func(r rune) bool {
		return r == ' ' || r == '\n' || r == '\t' || r == '\r'
	})
}

