package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

// ==================================================
// Phase J: FL8용 vocab JSON 내보내기
//
// 입력: real_corpus.txt
// 출력: data/vocab_fl8.json
//
// 포맷:
// {
//   "vocab": {"<PAD>":0, "<UNK>":1, ...},
//   "rev_vocab": {"0":"<PAD>", "1":"<UNK>", ...},
//   "vocab_size": 2004,
//   "merges": [["fn","add"], ...],    // BPE 머지 규칙 (선택)
//   "special": {"pad":0,"unk":1,"bos":2,"eos":3}
// }
// ==================================================

// FL8Vocab: FL8 런타임이 읽을 수 있는 vocab 포맷
type FL8Vocab struct {
	Vocab     map[string]int    `json:"vocab"`
	RevVocab  map[string]string `json:"rev_vocab"`   // key=숫자문자열
	VocabSize int               `json:"vocab_size"`
	Special   map[string]int    `json:"special"`
	TopWords  []string          `json:"top_words"`   // 상위 100 단어
}

// exportVocabFL8: corpus → vocab_fl8.json
func exportVocabFL8() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase J: FL8 Vocab 내보내기                                ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 1. corpus 로드
	fmt.Print("[1/4] corpus 로드... ")
	corpus, err := loadPhaseICorpus("data/real_corpus.txt", 500_000)
	if err != nil {
		corpus, err = loadPhaseICorpus("data/real_corpus_large.txt", 300_000)
		if err != nil {
			fmt.Printf("❌ %v\n", err)
			return
		}
	}
	fmt.Printf("✅ vocab=%d\n", corpus.vocabSize)

	// 2. rev_vocab 변환 (int key → string key, JSON은 string key만 지원)
	fmt.Print("[2/4] rev_vocab 변환... ")
	revVocabStr := make(map[string]string, len(corpus.revVocab))
	for id, token := range corpus.revVocab {
		revVocabStr[fmt.Sprintf("%d", id)] = token
	}
	fmt.Printf("✅ %d 항목\n", len(revVocabStr))

	// 3. 빈도순 상위 100 단어 추출
	fmt.Print("[3/4] 상위 단어 추출... ")
	type kv struct {
		k string
		v int
	}
	// 단어 빈도 재계산 (corpus.vocab은 id, 빈도 대신 정렬된 vocab 사용)
	// vocab에서 id 기준 정렬 → id가 낮을수록 빈도가 높음 (loadPhaseICorpus 기준)
	sorted := make([]kv, 0, len(corpus.vocab))
	for token, id := range corpus.vocab {
		sorted = append(sorted, kv{token, id})
	}
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].v < sorted[j].v })

	topN := 100
	if len(sorted) < topN {
		topN = len(sorted)
	}
	topWords := make([]string, topN)
	for i := 0; i < topN; i++ {
		topWords[i] = sorted[i].k
	}
	fmt.Printf("✅ top %d\n", topN)

	// 4. JSON 저장
	fmt.Print("[4/4] vocab_fl8.json 저장... ")
	fl8v := FL8Vocab{
		Vocab:    corpus.vocab,
		RevVocab: revVocabStr,
		VocabSize: corpus.vocabSize,
		Special: map[string]int{
			"pad": 0, "unk": 1, "bos": 2, "eos": 3,
		},
		TopWords: topWords,
	}

	data, err := json.MarshalIndent(fl8v, "", "  ")
	if err != nil {
		fmt.Printf("❌ marshal: %v\n", err)
		return
	}

	outPath := "data/vocab_fl8.json"
	if err2 := os.WriteFile(outPath, data, 0644); err2 != nil {
		fmt.Printf("❌ write: %v\n", err2)
		return
	}

	stat, _ := os.Stat(outPath)
	fmt.Printf("✅ %s (%d bytes)\n", outPath, stat.Size())

	// 출력 요약
	fmt.Printf("\n📊 FL8 Vocab 요약:\n")
	fmt.Printf("   vocab_size: %d\n", fl8v.VocabSize)
	fmt.Printf("   special:    PAD=%d UNK=%d BOS=%d EOS=%d\n",
		fl8v.Special["pad"], fl8v.Special["unk"], fl8v.Special["bos"], fl8v.Special["eos"])
	fmt.Printf("   top_10:     %s\n", strings.Join(topWords[:10], " | "))
	fmt.Printf("   저장 경로:   %s\n\n", outPath)
}

