// FreeLang v8 ML — GPT Tokenizer 표준 라이브러리 (Phase J)
//
// FL8 내장 함수:
//   tok_load(path)         → Tokenizer 핸들
//   tok_encode(tok, text)  → [id, id, ...]
//   tok_decode(tok, ids)   → "text"
//   tok_vocab_size(tok)    → n
//   tok_token(tok, id)     → "token"
//   tok_id(tok, token)     → id
//   tok_special(tok, name) → id   (name: "pad"|"unk"|"bos"|"eos")
//   tok_make(vocab_obj)    → Tokenizer 핸들 (인라인 vocab 사용)

import * as fs from 'fs';
import * as path from 'path';

// ============================================================
// FL8Vocab JSON 포맷
// ============================================================

export interface FL8VocabJSON {
  vocab: Record<string, number>;
  rev_vocab: Record<string, string>;
  vocab_size: number;
  special: Record<string, number>;
  top_words: string[];
}

// ============================================================
// FL8Tokenizer 클래스
// ============================================================

export class FL8Tokenizer {
  vocab:    Map<string, number>;   // token → id
  revVocab: Map<number, string>;   // id → token
  vocabSize: number;
  special:  Map<string, number>;   // "pad"|"unk"|"bos"|"eos" → id
  topWords: string[];

  constructor(data: FL8VocabJSON) {
    this.vocab    = new Map(Object.entries(data.vocab));
    this.revVocab = new Map(
      Object.entries(data.rev_vocab).map(([k, v]) => [parseInt(k), v])
    );
    this.vocabSize = data.vocab_size;
    this.special   = new Map(Object.entries(data.special ?? {}));
    this.topWords  = data.top_words ?? [];

    // special 기본값
    if (!this.special.has('pad')) this.special.set('pad', 0);
    if (!this.special.has('unk')) this.special.set('unk', 1);
    if (!this.special.has('bos')) this.special.set('bos', 2);
    if (!this.special.has('eos')) this.special.set('eos', 3);
  }

  // 파일에서 로드
  static fromFile(vocabPath: string): FL8Tokenizer {
    const resolved = path.resolve(vocabPath);
    const raw = fs.readFileSync(resolved, 'utf-8');
    const data: FL8VocabJSON = JSON.parse(raw);
    return new FL8Tokenizer(data);
  }

  // 인라인 vocab에서 생성 (테스트용)
  static fromVocab(vocab: Record<string, number>): FL8Tokenizer {
    const revVocab: Record<string, string> = {};
    for (const [token, id] of Object.entries(vocab)) {
      revVocab[String(id)] = token;
    }
    return new FL8Tokenizer({
      vocab,
      rev_vocab: revVocab,
      vocab_size: Object.keys(vocab).length,
      special: { pad: 0, unk: 1, bos: 2, eos: 3 },
      top_words: [],
    });
  }

  // 텍스트 → token id 배열 (공백 기준 분리)
  encode(text: string): number[] {
    const unk = this.special.get('unk') ?? 1;
    return text.split(/\s+/).filter(w => w.length > 0).map(w => {
      const id = this.vocab.get(w);
      return id !== undefined ? id : unk;
    });
  }

  // token id 배열 → 텍스트
  decode(ids: number[]): string {
    return ids.map(id => this.revVocab.get(id) ?? '<UNK>').join(' ');
  }

  // 단일 token → id
  tokenToId(token: string): number {
    return this.vocab.get(token) ?? (this.special.get('unk') ?? 1);
  }

  // 단일 id → token
  idToToken(id: number): string {
    return this.revVocab.get(id) ?? '<UNK>';
  }

  // special token id 반환
  specialId(name: string): number {
    return this.special.get(name) ?? 1;
  }
}

// ============================================================
// FL8 런타임 래퍼 (interpreter.ts에서 등록)
// ============================================================

export const FL8_TOKENIZER = {
  // tok_load(path) → FL8Tokenizer 핸들
  load(vocabPath: string): FL8Tokenizer {
    return FL8Tokenizer.fromFile(vocabPath);
  },

  // tok_make(vocab_obj) → FL8Tokenizer 핸들 (인라인)
  make(vocab: Record<string, number>): FL8Tokenizer {
    return FL8Tokenizer.fromVocab(vocab);
  },

  // tok_encode(tok, text) → number[]
  encode(tok: FL8Tokenizer, text: string): number[] {
    return tok.encode(text);
  },

  // tok_decode(tok, ids) → string
  decode(tok: FL8Tokenizer, ids: number[]): string {
    return tok.decode(ids);
  },

  // tok_vocab_size(tok) → number
  vocabSize(tok: FL8Tokenizer): number {
    return tok.vocabSize;
  },

  // tok_token(tok, id) → string
  token(tok: FL8Tokenizer, id: number): string {
    return tok.idToToken(id);
  },

  // tok_id(tok, token) → number
  id(tok: FL8Tokenizer, token: string): number {
    return tok.tokenToId(token);
  },

  // tok_special(tok, name) → number
  special(tok: FL8Tokenizer, name: string): number {
    return tok.specialId(name);
  },

  // tok_top_words(tok) → string[]
  topWords(tok: FL8Tokenizer): string[] {
    return tok.topWords;
  },
};

