// FreeLang v8 ML — Phase J 테스트
// FL8 GPT Tokenizer 브리지: 12개 테스트

import { FL8Tokenizer, FL8VocabJSON, FL8_TOKENIZER } from "../src/stdlib/tokenizer";
import { Interpreter } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";

// ============================================================
// 테스트 프레임워크
// ============================================================

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✅ PASS: ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ❌ FAIL: ${name} — ${e.message}`);
    failed++;
  }
}

function expect(actual: any, expected: any, msg = "") {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) throw new Error(`${msg} expected=${JSON.stringify(expected)} actual=${JSON.stringify(actual)}`);
}

function expectTrue(cond: boolean, msg = "") {
  if (!cond) throw new Error(msg || "기대값 true");
}

// ============================================================
// 테스트용 인라인 vocab
// ============================================================

const MINI_VOCAB: Record<string, number> = {
  "<PAD>": 0, "<UNK>": 1, "<BOS>": 2, "<EOS>": 3,
  "fn": 4, "let": 5, "return": 6, "if": 7, "else": 8,
  "for": 9, "while": 10, "in": 11, "range": 12,
  "->": 13, "i32": 14, "f32": 15, "str": 16,
  "print": 17, "true": 18, "false": 19,
  "FreeLang": 20, "GPT": 21, "Phase": 22, "ML": 23,
};

// ============================================================
// Suite 1: FL8Tokenizer 클래스 (TypeScript 유닛)
// ============================================================

console.log("\n── Suite 1: FL8Tokenizer 클래스 ──────────────────────────────");

test("fromVocab 생성 및 vocabSize", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  expect(tok.vocabSize, Object.keys(MINI_VOCAB).length);
});

test("encode: 알려진 단어 → id 배열", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  const ids = tok.encode("fn let return");
  expect(ids, [4, 5, 6]);
});

test("decode: id 배열 → 텍스트", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  const text = tok.decode([4, 5, 6]);
  expect(text, "fn let return");
});

test("encode/decode 왕복", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  const src = "FreeLang GPT Phase ML";
  const ids = tok.encode(src);
  const back = tok.decode(ids);
  expect(back, src);
});

test("미지 단어 → UNK id (1)", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  const ids = tok.encode("unknown_xyz_word");
  expect(ids, [1]); // UNK
});

test("special token: pad/unk/bos/eos", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  expect(tok.specialId("pad"), 0);
  expect(tok.specialId("unk"), 1);
  expect(tok.specialId("bos"), 2);
  expect(tok.specialId("eos"), 3);
});

test("tokenToId / idToToken 왕복", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  const id = tok.tokenToId("fn");
  expect(id, 4);
  const token = tok.idToToken(4);
  expect(token, "fn");
});

test("FL8VocabJSON 포맷 직렬화", () => {
  const tok = FL8Tokenizer.fromVocab(MINI_VOCAB);
  // rev_vocab 검증
  expect(tok.revVocab.get(4), "fn");
  expect(tok.revVocab.get(20), "FreeLang");
});

