let tok = tok_make(pairs)
let ids = tok_encode(tok, "fn let return")
len(ids)
`;
  const result = runFL8(src);
  expect(result.val, 3);
});

test("tok_decode FL8 소스", () => {
  const src = `
let pairs = [["fn",4],["let",5],["<PAD>",0],["<UNK>",1],["<BOS>",2],["<EOS>",3]]
let tok = tok_make(pairs)
tok_decode(tok, [4, 5])
`;
  const result = runFL8(src);
  expect(result.val, "fn let");
});

test("tok_special FL8 소스", () => {
  const src = `
let pairs = [["<PAD>",0],["<UNK>",1],["<BOS>",2],["<EOS>",3]]
let tok = tok_make(pairs)
tok_special(tok, "bos")
`;
  const result = runFL8(src);
  expect(result.val, 2);
});

