// FreeLang v8 ML — GPT Embedding (Phase K)
//
// token embedding + positional embedding
// 내장 함수: zeros(rows, cols), t_row, t_set_row, t_add, randn

// ─── embedding 행렬 초기화 ────────────────────────────────────
// make_embed(vocab_size, d_model) → [vocab_size, d_model] tensor

fn make_embed(vocab_size: i32, d_model: i32) -> i32 {
  return 0
}

// embed_lookup(table, token_id) → [d_model] 1D tensor
// table: [vocab_size, d_model]

fn embed_lookup(table: i32, token_id: i32) -> i32 {
  return t_row(table, token_id)
}

// embed_seq(table, ids) → [seq_len, d_model] 2D tensor
