// FreeLang v8 ML — GPT Causal Self-Attention (Phase K)
//
// 단일 헤드 causal self-attention
//   Q = X @ Wq   [seq, d]
//   K = X @ Wk   [seq, d]
//   V = X @ Wv   [seq, d]
//   scores = Q @ K^T / sqrt(d)  + causal_mask
//   attn = softmax(scores, row)
//   out = attn @ V
//   return out @ Wo

// ─── linear 연산 (bias 포함) ─────────────────────────────────
// linear_fwd(x, W, b) → [seq, out_dim]
//   x: [seq, in_dim], W: [in_dim, out_dim], b: [out_dim]

fn linear_fwd(x: i32, W: i32, b: i32, seq_len: i32, out_dim: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(out, i)
    let new_row = t_add(row, b)
    t_set_row(out, i, new_row)
  }
  return out
}

// ─── row-wise softmax ─────────────────────────────────────────
// row_softmax(t) → 각 행에 softmax 적용 [seq, seq]

fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    let row = t_row(t, i)
    let sm = t_softmax(row)
    t_set_row(out, i, sm)
  }
  return out
}

// ─── causal self-attention ────────────────────────────────────
// attn_fwd(x, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d)
//   → [seq_len, d]

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            seq_len: i32, d: i32) -> i32 {
  // Q, K, V 프로젝션
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)

  // scores = Q @ K^T / sqrt(d)
  let Kt = transpose(K)
  let scores = matmul(Q, Kt)
  let scale = 1.0 / sqrt(float(d))
  let scores_scaled = t_scale(scores, scale)

  // causal mask 추가
  let mask = t_causal_mask(seq_len)
  let scores_masked = t_add(scores_scaled, mask)

  // row-wise softmax
  let attn_w = row_softmax(scores_masked, seq_len, seq_len)

  // context = attn_w @ V
  let ctx = matmul(attn_w, V)

  // output projection
  let out = linear_fwd(ctx, Wo, bo, seq_len, d)
  return out
}

