// FreeLang v8 ML — Phase K 테스트
// FL8 LLM 핵심 모듈: 25개 테스트

import { Interpreter } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";

let passed = 0, failed = 0;

function test(name: string, fn: () => void) {
  try { fn(); console.log(`  ✅ PASS: ${name}`); passed++; }
  catch (e: any) { console.log(`  ❌ FAIL: ${name} — ${e.message}`); failed++; }
}

function expect(actual: any, expected: any, msg = "") {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) throw new Error(`${msg} expected=${JSON.stringify(expected)} got=${JSON.stringify(actual)}`);
}

function expectClose(a: number, b: number, tol = 0.001, msg = "") {
  if (Math.abs(a - b) > tol) throw new Error(`${msg} |${a} - ${b}| > ${tol}`);
}

function runFL8(src: string): any {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  return interp.run(program);
}

function runFL8Interp(src: string): Interpreter {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  interp.run(program);
  return interp;
}

// ============================================================
// Suite 1: 새 tensor 내장 함수
// ============================================================
console.log("\n── Suite 1: 새 tensor 내장 함수 ──────────────────────────────");

test("t_add: elementwise 덧셈", () => {
  const r = runFL8(`
let a = zeros(2, 3)
let b = ones(2, 3)
let c = t_add(a, b)
tget(c, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "t_add");
});

test("t_scale: scalar 곱", () => {
  const r = runFL8(`
let a = ones(2, 2)
let b = t_scale(a, 3.0)
tget(b, 1, 1)
`);
  expectClose(r.val, 3.0, 0.001, "t_scale");
});

test("t_row/t_set_row 왕복", () => {
  const r = runFL8(`
let t = zeros(3, 4)
let row = ones(4)
let row1 = reshape(row, 4)
t_set_row(t, 1, row1)
let got = t_row(t, 1)
tget(got, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "t_row");
});

test("t_softmax: 합=1", () => {
  const r = runFL8(`
let v = randn(8)
let v1 = reshape(v, 8)
let sm = t_softmax(v1)
t_sum(sm)
`);
  expectClose(r.val, 1.0, 0.001, "softmax sum");
});

test("t_layer_norm: 정규화", () => {
  const r = runFL8(`
let x = ones(4)
let x1 = reshape(x, 4)
let s = ones(4)
let s1 = reshape(s, 4)
let b = zeros(4)
let b1 = reshape(b, 4)
let out = t_layer_norm(x1, s1, b1, 0.00001)
t_mean(out)
`);
  expectClose(r.val, 0.0, 0.01, "layer_norm mean≈0");
});

test("t_gelu: 양수 x > 0", () => {
  const r = runFL8(`
let x = ones(4)
let x1 = reshape(x, 4)
let out = t_gelu(x1)
tget(out, 0, 0)
`);
  if (r.val <= 0) throw new Error(`gelu(1) should be > 0, got ${r.val}`);
});

test("t_causal_mask: 대각선 아래=0, 위=-1e9", () => {
  const r = runFL8(`
let m = t_causal_mask(3)
tget(m, 0, 1)
`);
  if (r.val >= -1e8) throw new Error(`causal mask[0,1] should be -1e9, got ${r.val}`);
});

test("t_argmax: 최댓값 인덱스", () => {
  const r = runFL8(`
let v = [0.1, 0.9, 0.3, 0.05]
let t = tensor(v, 4)
t_argmax(t)
`);
  expect(r.val, 1, "argmax");
});

test("t_rows / t_cols", () => {
  const r = runFL8(`
let m = zeros(3, 5)
let r = t_rows(m)
let c = t_cols(m)
r * 10 + c
`);
  expectClose(r.val, 35, 0.001, "rows=3 cols=5");
});

test("t_fill: 상수 텐서", () => {
  const r = runFL8(`
let m = t_fill(2, 3, 7.0)
tget(m, 1, 2)
`);
  expectClose(r.val, 7.0, 0.001, "t_fill");
});

// ============================================================
// Suite 2: gpt_embedding 모듈
// ============================================================
console.log("\n── Suite 2: gpt_embedding 모듈 ────────────────────────────────");

const EMBED_SETUP = `
fn embed_seq(table: i32, ids: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}
fn embed_forward(tok_t: i32, pos_t: i32, ids: i32, seq_len: i32, d: i32) -> i32 {
  let te = embed_seq(tok_t, ids, seq_len, d)
  let pe = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let r = t_row(pos_t, i)
    t_set_row(pe, i, r)
  }
  return t_add(te, pe)
}
`;

test("embed_seq: shape [seq, d]", () => {
  const r = runFL8(EMBED_SETUP + `
let tab = randn(10, 8)
let ids = [2, 5, 1, 8]
let out = embed_seq(tab, ids, 4, 8)
t_rows(out) * 100 + t_cols(out)
`);
  expectClose(r.val, 408, 0.001, "embed_seq shape");
});

test("embed_forward: token+pos 덧셈", () => {
  const r = runFL8(EMBED_SETUP + `
let tok_t = zeros(10, 4)
let pos_t = ones(6, 4)
let ids = [0, 1, 2]
let out = embed_forward(tok_t, pos_t, ids, 3, 4)
tget(out, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "embed_forward zero+one=one");
});

test("embed_lookup: 올바른 행 반환", () => {
  const r = runFL8(`
let tab = t_fill(5, 4, 0.0)
let row2 = t_fill(1, 4, 9.0)
let row2_1d = reshape(row2, 4)
t_set_row(tab, 2, row2_1d)
let got = t_row(tab, 2)
tget(got, 0, 0)
`);
  expectClose(r.val, 9.0, 0.001, "embed_lookup row2");
});

// ============================================================
// Suite 3: gpt_attention 모듈
// ============================================================
console.log("\n── Suite 3: gpt_attention 모듈 ────────────────────────────────");

const ATTN_SETUP = `
fn linear_fwd(x: i32, W: i32, b: i32, sl: i32, od: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(sl) {
    let r = t_row(out, i)
    t_set_row(out, i, t_add(r, b))
  }
  return out
}
fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    t_set_row(out, i, t_softmax(t_row(t, i)))
  }
  return out
}
fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            sl: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, sl, d)
  let K = linear_fwd(x, Wk, bk, sl, d)
  let V = linear_fwd(x, Wv, bv, sl, d)
  let sc = t_scale(matmul(Q, transpose(K)), 1.0 / sqrt(float(d)))
  let mask = t_causal_mask(sl)
  let aw = row_softmax(t_add(sc, mask), sl, sl)
  return linear_fwd(matmul(aw, V), Wo, bo, sl, d)
}
`;

test("attn_fwd: output shape [seq, d]", () => {
  const r = runFL8(ATTN_SETUP + `
let sl = 4
let d = 8
let x = randn(sl, d)
let Wq = randn(d, d)
let Wk = randn(d, d)
let Wv = randn(d, d)
let Wo = randn(d, d)
let b = reshape(zeros(d), d)
let out = attn_fwd(x, Wq, Wk, Wv, Wo, b, b, b, b, sl, d)
t_rows(out) * 100 + t_cols(out)
`);
  expectClose(r.val, 408, 0.001, "attn shape [4,8]");
});

test("attn_fwd: causal mask 적용 (NaN 없음)", () => {
  const r = runFL8(ATTN_SETUP + `
let sl = 3
let d = 4
let x = randn(sl, d)
let W = randn(d, d)
let b = reshape(zeros(d), d)
let out = attn_fwd(x, W, W, W, W, b, b, b, b, sl, d)
let v = tget(out, 0, 0)
if v == v { 1 } else { 0 }
`);
  expect(r.val, 1, "NaN check");
});

test("row_softmax: 각 행 합=1", () => {
  const r = runFL8(ATTN_SETUP + `
let m = randn(3, 3)
let sm = row_softmax(m, 3, 3)
let row0 = t_row(sm, 0)
t_sum(row0)
`);
  expectClose(r.val, 1.0, 0.001, "row softmax sum");
});

// ============================================================
// Suite 4: gpt_block 모듈
// ============================================================
console.log("\n── Suite 4: gpt_block 모듈 ────────────────────────────────────");

const BLOCK_PREAMBLE = `
fn linear_fwd(x: i32, W: i32, b: i32, sl: i32, od: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(sl) { t_set_row(out, i, t_add(t_row(out, i), b)) }
  return out
}
fn row_softmax(t: i32, r: i32, c: i32) -> i32 {
  let out = zeros(r, c)
  let i = 0
  for i in range(r) { t_set_row(out, i, t_softmax(t_row(t, i))) }
  return out
}
fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32, sl: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, sl, d)
  let K = linear_fwd(x, Wk, bk, sl, d)
  let V = linear_fwd(x, Wv, bv, sl, d)
  let sc = t_scale(matmul(Q, transpose(K)), 1.0 / sqrt(float(d)))
  let aw = row_softmax(t_add(sc, t_causal_mask(sl)), sl, sl)
  return linear_fwd(matmul(aw, V), Wo, bo, sl, d)
}
fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(sl) { t_set_row(h, i, t_add(t_row(h, i), b1)) }
  let ha = t_gelu(h)
  let out = matmul(ha, W2)
  for i in range(sl) { t_set_row(out, i, t_add(t_row(out, i), b2)) }
  return out
}
fn row_ln(x: i32, sc: i32, bi: i32, sl: i32, d: i32) -> i32 {
  let out = zeros(sl, d)
  let i = 0
  for i in range(sl) { t_set_row(out, i, t_layer_norm(t_row(x, i), sc, bi, 0.00001)) }
  return out
}
fn block_fwd(x: i32,
  Wq: i32, Wk: i32, Wv: i32, Wo: i32, bq: i32, bk: i32, bv: i32, bo: i32,
  W1: i32, b1: i32, W2: i32, b2: i32,
  ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
  sl: i32, d: i32, fd: i32) -> i32 {
  let x1 = row_ln(x, ln1s, ln1b, sl, d)
  let ao = attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, sl, d)
  let x2 = t_add(x, ao)
  let x3 = row_ln(x2, ln2s, ln2b, sl, d)
  return t_add(x2, ffn_fwd(x3, W1, b1, W2, b2, sl, d, fd))
}
`;

test("block_fwd: shape 보존 [sl, d]", () => {
  const r = runFL8(BLOCK_PREAMBLE + `
let sl=4 let d=8 let fd=16
let x=randn(sl,d)
let W=randn(d,d) let b=reshape(zeros(d),d)
let W1=randn(d,fd) let b1=reshape(zeros(fd),fd)
let W2=randn(fd,d) let b2=reshape(zeros(d),d)
let ls=reshape(ones(d),d) let lb=reshape(zeros(d),d)
let out=block_fwd(x,W,W,W,W,b,b,b,b,W1,b1,W2,b2,ls,lb,ls,lb,sl,d,fd)
t_rows(out)*100+t_cols(out)
`);
  expectClose(r.val, 408, 0.001, "block shape");
});

test("block_fwd: residual 연결 (입력 유사성)", () => {
  const r = runFL8(BLOCK_PREAMBLE + `
let sl=2 let d=4 let fd=8
let x=zeros(sl,d)
let W=randn(d,d) let b=reshape(zeros(d),d)
let W1=randn(d,fd) let b1=reshape(zeros(fd),fd)
let W2=randn(fd,d) let b2=reshape(zeros(d),d)
let ls=reshape(ones(d),d) let lb=reshape(zeros(d),d)
let out=block_fwd(x,W,W,W,W,b,b,b,b,W1,b1,W2,b2,ls,lb,ls,lb,sl,d,fd)
t_rows(out)
`);
  expect(r.val, 2, "residual rows=2");
});

// ============================================================
// Suite 5: gpt_model forward pass
// ============================================================
console.log("\n── Suite 5: gpt_model forward ─────────────────────────────────");

test("model_forward: logits shape [vocab_size]", () => {
  // gpt_model.fl8 전체 실행
  const r = runFL8(BLOCK_PREAMBLE + EMBED_SETUP + `
fn layer_fwd(x: i32, params: i32, li: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let b = li * 16
  return block_fwd(x,
    params[b+0],params[b+1],params[b+2],params[b+3],
    params[b+4],params[b+5],params[b+6],params[b+7],
    params[b+8],params[b+9],params[b+10],params[b+11],
    params[b+12],params[b+13],params[b+14],params[b+15],
    sl, d, fd)
}
fn make_layer(d: i32, fd: i32) -> i32 {
  let p = []
  let i = 0
  for i in range(4) { push(p, randn(d,d)) }
  for i in range(4) { push(p, reshape(zeros(d),d)) }
  push(p, randn(d,fd))  push(p, reshape(zeros(fd),fd))
  push(p, randn(fd,d))  push(p, reshape(zeros(d),d))
  push(p, reshape(ones(d),d))  push(p, reshape(zeros(d),d))
  push(p, reshape(ones(d),d))  push(p, reshape(zeros(d),d))
  return p
}
let vocab=20 let d=8 let fd=16 let nl=2 let sl=4
let tok_t = randn(vocab, d)
let pos_t = randn(sl, d)
let ap = []
let i = 0
for i in range(nl) {
  let lp = make_layer(d, fd)
  let pi = 0
  for pi in range(16) { push(ap, lp[pi]) }
}
let fls = reshape(ones(d),d)
let flb = reshape(zeros(d),d)
let lm_head = randn(d, vocab)
let lm_bias = reshape(zeros(vocab), vocab)
let ids = [3,7,1,5]
let x = embed_forward(tok_t, pos_t, ids, sl, d)
for i in range(nl) { x = layer_fwd(x, ap, i, sl, d, fd) }
let last = t_layer_norm(t_row(x, sl-1), fls, flb, 0.00001)
let lg2d = reshape(last, 1, d)
let lg = t_row(matmul(lg2d, lm_head), 0)
let logits = t_add(lg, lm_bias)
len(shape(logits))
`);
  expect(r.val, 1, "logits는 1D");
});

test("model_forward: softmax 확률 합=1", () => {
  const r = runFL8(BLOCK_PREAMBLE + `
let vocab=10 let d=4
let lm_head = randn(d, vocab)
let last = randn(d)
let last1 = reshape(last, d)
let lg2d = reshape(last1, 1, d)
let lg = t_row(matmul(lg2d, lm_head), 0)
let probs = t_softmax(lg)
t_sum(probs)
`);
  expectClose(r.val, 1.0, 0.001, "probs sum=1");
});

test("model_forward: argmax는 [0, vocab_size) 범위", () => {
  const r = runFL8(BLOCK_PREAMBLE + `
let vocab=15 let d=6
let lm_head = randn(d, vocab)
let last = randn(d)
let last1 = reshape(last, d)
let lg = t_row(matmul(reshape(last1, 1, d), lm_head), 0)
let pred = t_argmax(lg)
pred
`);
  if (r.val < 0 || r.val >= 15)
    throw new Error(`argmax=${r.val} out of [0,15)`);
});

// ============================================================
// 결과
// ============================================================
console.log(`\n${"═".repeat(55)}`);
console.log(`Phase K 결과: ${passed}/${passed + failed} PASS`);
if (failed > 0) { console.log(`❌ FAIL: ${failed}개`); process.exit(1); }
else console.log("✅ ALL PASS");

