// ── Phase L: 학습 루프용 내장 함수 ──────────────────────────

// t_ce_loss(logits, target_id) → scalar (cross-entropy loss, 1D logits)
g.set("t_ce_loss", { tag: "builtin", fn: (logits, targetId) => {
  const d = asTensor(logits).data;
  const t = asNum(targetId);
  const maxV = Math.max(...d);
  const exps = d.map(v => Math.exp(v - maxV));
  const sumE = exps.reduce((a, b) => a + b, 0);
  const loss = -Math.log(exps[t] / sumE + 1e-12);
  return num(loss);
}});

// t_log_softmax(t) → 1D log-softmax 텐서
g.set("t_log_softmax", builtin1((t) => {
  const d = asTensor(t).data;
  const maxV = Math.max(...d);
  const exps = d.map(v => Math.exp(v - maxV));
  const sumE = exps.reduce((a, b) => a + b, 0);
  const logSm = exps.map(v => Math.log(v / sumE + 1e-12));
  return { tag: "tensor", data: logSm, shape: [logSm.length] };
}));

// t_zeros_like(t) → 같은 shape의 0 텐서
g.set("t_zeros_like", builtin1((t) => {
  const ten = asTensor(t);
  return { tag: "tensor", data: Array(ten.data.length).fill(0), shape: [...ten.shape] };
}));

// t_ones_like(t) → 같은 shape의 1 텐서
g.set("t_ones_like", builtin1((t) => {
  const ten = asTensor(t);
  return { tag: "tensor", data: Array(ten.data.length).fill(1), shape: [...ten.shape] };
}));

// t_clip(t, lo, hi) → elementwise clamp
g.set("t_clip", { tag: "builtin", fn: (t, lo, hi) => {
  const ten = asTensor(t);
  const l = asNum(lo), h = asNum(hi);
  const data = ten.data.map(v => Math.min(Math.max(v, l), h));
  return { tag: "tensor", data, shape: [...ten.shape] };
}});

// t_sqrt(t) → elementwise sqrt
g.set("t_sqrt", builtin1((t) => {
  const ten = asTensor(t);
  const data = ten.data.map(v => Math.sqrt(Math.abs(v)));
  return { tag: "tensor", data, shape: [...ten.shape] };
}));

// t_div(a, b) → elementwise 나눗셈 (텐서/텐서 or 텐서/스칼라)
g.set("t_div", { tag: "builtin", fn: (a, b) => {
  const ta = asTensor(a);
  if (b.tag === "number") {
    const s = asNum(b);
    return { tag: "tensor", data: ta.data.map(v => v / s), shape: [...ta.shape] };
  }
  const tb = asTensor(b);
  return { tag: "tensor", data: ta.data.map((v, i) => v / (tb.data[i] + 1e-12)), shape: [...ta.shape] };
}});

// t_pow2(t) → elementwise 제곱 (t^2)
g.set("t_pow2", builtin1((t) => {
  const ten = asTensor(t);
  const data = ten.data.map(v => v * v);
  return { tag: "tensor", data, shape: [...ten.shape] };
}));

// t_flatten(t) → 1D tensor (모든 원소)
g.set("t_flatten", builtin1((t) => {
  const ten = asTensor(t);
