test("ce_loss: 낮은 loss (정답 logit 높음)", () => {
  const r = runFL8(`
fn ce_loss(logits: i32, target_id: i32) -> i32 {
  return t_ce_loss(logits, target_id)
}
let v = reshape(zeros(8), 8)
t_set(v, 5, 10.0)
ce_loss(v, 5)
`);
  expectLt(r.val, 0.1, "low ce_loss");
});

test("ce_loss: 높은 loss (오답)", () => {
  const r = runFL8(`
fn ce_loss(logits: i32, target_id: i32) -> i32 {
  return t_ce_loss(logits, target_id)
}
let v = reshape(zeros(8), 8)
t_set(v, 5, 10.0)
ce_loss(v, 0)
`);
  expectGt(r.val, 5.0, "high ce_loss");
});

test("seq_ce_loss: 평균 반환", () => {
  const r = runFL8(`
fn seq_ce_loss(logits_2d: i32, target_ids: i32, seq_len: i32, vocab_size: i32) -> i32 {
  let total_loss = 0.0
  let i = 0
  for i in range(seq_len) {
    let logits_row = t_row(logits_2d, i)
    let tid = int(target_ids[i])
    let loss = t_ce_loss(logits_row, tid)
    total_loss = total_loss + loss
  }
  return total_loss / float(seq_len)
}
let logits_2d = zeros(3, 5)
let targets = [0, 1, 2]
seq_ce_loss(logits_2d, targets, 3, 5)
`);
  // uniform → -log(1/5) ≈ 1.609
  expectClose(r.val, Math.log(5), 0.05, "seq_ce_loss uniform");
});

