// ============================================================
console.log("\n── Suite 2: gpt_loss 모듈 ───────────────────────────────────");

test("ce_loss: 낮은 loss (정답 logit 높음)", () => {
  const r = runFL8(`
fn ce_loss(logits: i32, target_id: i32) -> i32 {
  return t_ce_loss(logits, target_id)
}
let v = reshape(zeros(8), 8)
t_set(v, 5, 10.0)
ce_loss(v, 5)
`);
  expectLt(r.val, 0.1, "low ce_loss");
});

test("ce_loss: 높은 loss (오답)", () => {
  const r = runFL8(`
fn ce_loss(logits: i32, target_id: i32) -> i32 {
  return t_ce_loss(logits, target_id)
}
let v = reshape(zeros(8), 8)
t_set(v, 5, 10.0)
ce_loss(v, 0)
`);
  expectGt(r.val, 5.0, "high ce_loss");
});

test("seq_ce_loss: 평균 반환", () => {
  const r = runFL8(`
fn seq_ce_loss(logits_2d: i32, target_ids: i32, seq_len: i32, vocab_size: i32) -> i32 {
  let total_loss = 0.0
  let i = 0
  for i in range(seq_len) {
    let logits_row = t_row(logits_2d, i)
    let tid = int(target_ids[i])
    let loss = t_ce_loss(logits_row, tid)
    total_loss = total_loss + loss
  }
  return total_loss / float(seq_len)
}
let logits_2d = zeros(3, 5)
let targets = [0, 1, 2]
seq_ce_loss(logits_2d, targets, 3, 5)
`);
  // uniform → -log(1/5) ≈ 1.609
  expectClose(r.val, Math.log(5), 0.05, "seq_ce_loss uniform");
});

// ============================================================
// Suite 3: gpt_adam 모듈
// ============================================================
console.log("\n── Suite 3: gpt_adam 모듈 ───────────────────────────────────");

test("make_adam_state: [m, v, step] 구조", () => {
  const r = runFL8(`
fn make_adam_state(param: i32) -> i32 {
  let state = []
  push(state, t_zeros_like(param))
  push(state, t_zeros_like(param))
  push(state, 0)
  return state
}
let p = reshape(randn(4), 4)
let s = make_adam_state(p)
len(s)
`);
  expect(r.val, 3, "adam_state len=3");
});

test("adam_update: 파라미터 변화 (gradient 방향 감소)", () => {
  const r = runFL8(`
fn make_adam_state(param: i32) -> i32 {
  let state = []
  push(state, t_zeros_like(param))
  push(state, t_zeros_like(param))
  push(state, 0)
  return state
}
fn adam_update(param: i32, grad: i32, state: i32,
               lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let m = state[0]
  let v = state[1]
  let step = state[2] + 1
  state[2] = step
  let m_new = t_add(t_scale(m, b1), t_scale(grad, 1.0 - b1))
  state[0] = m_new
  let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(grad), 1.0 - b2))
  state[1] = v_new
  let bc1 = 1.0 - pow(b1, float(step))
  let bc2 = 1.0 - pow(b2, float(step))
  let m_hat = t_scale(m_new, 1.0 / bc1)
  let v_hat = t_scale(v_new, 1.0 / bc2)
  let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
  let delta = t_scale(t_div(m_hat, denom), lr)
  return t_sub(param, delta)
}
let p = reshape(zeros(4), 4)
let g = reshape(ones(4), 4)
let st = make_adam_state(p)
let p2 = adam_update(p, g, st, 0.01, 0.9, 0.999, 0.00000001)
t_sum(p2)
`);
  // p는 zeros → sum=0, p2는 음수 방향 → sum<0
  expectLt(r.val, 0, "adam decreases param with positive grad");
});

test("adam_update: step count 증가", () => {
  const r = runFL8(`
fn make_adam_state(param: i32) -> i32 {
  let state = []
  push(state, t_zeros_like(param))
  push(state, t_zeros_like(param))
  push(state, 0)
  return state
}
fn adam_update(param: i32, grad: i32, state: i32,
               lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let m = state[0]
  let v = state[1]
  let step = state[2] + 1
  state[2] = step
  let m_new = t_add(t_scale(m, b1), t_scale(grad, 1.0 - b1))
  state[0] = m_new
  let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(grad), 1.0 - b2))
  state[1] = v_new
  let bc1 = 1.0 - pow(b1, float(step))
  let bc2 = 1.0 - pow(b2, float(step))
  let m_hat = t_scale(m_new, 1.0 / bc1)
  let v_hat = t_scale(v_new, 1.0 / bc2)
  let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
  let delta = t_scale(t_div(m_hat, denom), lr)
  return t_sub(param, delta)
}
let p = reshape(zeros(4), 4)
let g = reshape(ones(4), 4)
let st = make_adam_state(p)
adam_update(p, g, st, 0.01, 0.9, 0.999, 0.00000001)
adam_update(p, g, st, 0.01, 0.9, 0.999, 0.00000001)
st[2]
`);
  expect(r.val, 2, "step count=2");
});

