// FreeLang v8 ML — Phase M 테스트
// FL8 GPT 추론: gpt_inference.fl8 검증
// 총 15개 테스트

import { Interpreter } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";
import * as fs from "fs";
import * as path from "path";

let passed = 0, failed = 0;

function test(name: string, fn: () => void) {
  try { fn(); console.log(`  ✅ PASS: ${name}`); passed++; }
  catch (e: any) { console.log(`  ❌ FAIL: ${name} — ${e.message}`); failed++; }
}

function expectClose(a: number, b: number, tol = 0.001, msg = "") {
  if (Math.abs(a - b) > tol) throw new Error(`${msg} |${a} - ${b}| > ${tol}`);
}

function expectLt(a: number, b: number, msg = "") {
  if (a >= b) throw new Error(`${msg}: ${a} >= ${b}`);
}

function expectGt(a: number, b: number, msg = "") {
  if (a <= b) throw new Error(`${msg}: ${a} <= ${b}`);
}

function expectRange(a: number, lo: number, hi: number, msg = "") {
  if (a < lo || a >= hi) throw new Error(`${msg}: ${a} not in [${lo}, ${hi})`);
}

function runFL8(src: string): any {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  return interp.run(program);
}

// gpt_inference.fl8 소스 로드
const inferenceScript = fs.readFileSync(
  path.join(__dirname, "../src/gpt/gpt_inference.fl8"), "utf-8"
);

// ============================================================
// Suite 1: top_k_sample 및 autoregressive 헬퍼
// ============================================================
console.log("\n── Suite 1: 추론 헬퍼 함수 ──────────────────────────────────");

test("top_k_sample: 결과가 [0, vocab) 범위", () => {
  const r = runFL8(`
let vocab = 10
let logits = reshape(randn(vocab), vocab)
let probs  = t_softmax(t_scale(logits, 1.0 / 0.8))
t_argmax(probs)
`);
  expectRange(r.val, 0, 10, "top_k_sample range");
});

test("temperature=0.01 → deterministic (항상 argmax)", () => {
  // 매우 낮은 온도 → softmax가 거의 one-hot → argmax 동일
  const r1 = runFL8(`
let logits = reshape(zeros(8), 8)
t_set(logits, 3, 10.0)
let probs = t_softmax(t_scale(logits, 1.0 / 0.01))
t_argmax(probs)
`);
  const r2 = runFL8(`
let logits = reshape(zeros(8), 8)
t_set(logits, 3, 10.0)
let probs = t_softmax(t_scale(logits, 1.0 / 0.01))
t_argmax(probs)
`);
  if (r1.val !== r2.val) throw new Error(`low temp not deterministic: ${r1.val} vs ${r2.val}`);
});

test("autoregressive: seed_ids에서 max_new 토큰 추가", () => {
  const r = runFL8(`
let vocab  = 10
let d      = 4
let ffn    = 8
let layers = 1
let max_s  = 6

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_row(table, int(ids[i])))
  }
  return out
}

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    t_set_row(pos_e, i, t_row(pos_table, i))
  }
  return t_add(tok_e, pos_e)
}

fn linear_fwd(x: i32, W: i32, b: i32, seq_len: i32, out_dim: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b))
  }
  return out
}

fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    t_set_row(out, i, t_softmax(t_row(t, i)))
  }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32, seq_len: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)
  let sm2 = t_add(t_scale(matmul(Q, transpose(K)), 1.0/sqrt(float(d))), t_causal_mask(seq_len))
  return linear_fwd(matmul(row_softmax(sm2, seq_len, seq_len), V), Wo, bo, seq_len, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32, seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) { t_set_row(h, i, t_add(t_row(h, i), b1)) }
  let out = matmul(t_gelu(h), W2)
  for i in range(seq_len) { t_set_row(out, i, t_add(t_row(out, i), b2)) }
  return out
}

fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_layer_norm(t_row(x, i), scale, bias, 0.00001))
  }
  return out
}

fn block_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let x1 = row_layer_norm(x, ln1s, ln1b, seq_len, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d))
  return t_add(x2, ffn_fwd(row_layer_norm(x2, ln2s, ln2b, seq_len, d), W1, b1, W2, b2, seq_len, d, ffn_dim))
}

fn layer_fwd(x: i32, params: i32, li: i32, seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    params[base+0], params[base+1], params[base+2], params[base+3],
    params[base+4], params[base+5], params[base+6], params[base+7],
    params[base+8], params[base+9], params[base+10], params[base+11],
    params[base+12], params[base+13], params[base+14], params[base+15],
    seq_len, d, ffn_dim)
}

