package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func main() {
	homeDir, _ := os.UserHomeDir()
	projectsDir := filepath.Join(homeDir, "projects")

	var texts []string
	err := filepath.WalkDir(projectsDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() && (d.Name() == ".git" || d.Name() == "node_modules" || d.Name() == "vendor") {
			return filepath.SkipDir
		}
		if !d.IsDir() && strings.HasSuffix(path, ".md") {
			data, e := os.ReadFile(path)
			if e == nil && len(data) > 0 {
				texts = append(texts, string(data))
			}
		}
		return nil
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "walk error: %v\n", err)
		os.Exit(1)
	}

	corpus := strings.Join(texts, "\n\n---\n\n")

	// vocab: byte-level 0-255, just find which bytes appear
	byteSet := make(map[byte]bool)
	for i := 0; i < len(corpus); i++ {
		byteSet[corpus[i]] = true
	}
	var vocab []byte
	for b := range byteSet {
		vocab = append(vocab, b)
	}
	sort.Slice(vocab, func(i, j int) bool { return vocab[i] < vocab[j] })

	// Write corpus
	outDir := filepath.Join(homeDir, "projects/freelang-llm/data")
	os.WriteFile(filepath.Join(outDir, "corpus.txt"), []byte(corpus), 0644)

	// Write vocab
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("vocab_size=%d\n", len(vocab)))
	for i, b := range vocab {
		sb.WriteString(fmt.Sprintf("%d=%d\n", i, b))
	}
	os.WriteFile(filepath.Join(outDir, "vocab.txt"), []byte(sb.String()), 0644)

	fmt.Printf("corpus: %d bytes, %d md files, vocab_size: %d\n", len(corpus), len(texts), len(vocab))
}
