package model

import (
	"math"
	"math/rand"
)

// Matrix: rows x cols, row-major
type Matrix struct {
	Data []float32
	Rows int
	Cols int
}

func NewMatrix(rows, cols int) *Matrix {
	return &Matrix{Data: make([]float32, rows*cols), Rows: rows, Cols: cols}
}

func (m *Matrix) At(r, c int) float32 { return m.Data[r*m.Cols+c] }
func (m *Matrix) Set(r, c int, v float32) { m.Data[r*m.Cols+c] = v }

func (m *Matrix) Clone() *Matrix {
	c := NewMatrix(m.Rows, m.Cols)
	copy(c.Data, m.Data)
	return c
}

func RandMatrix(rows, cols int, scale float32) *Matrix {
	m := NewMatrix(rows, cols)
	for i := range m.Data {
		m.Data[i] = float32(rand.NormFloat64()) * scale
	}
	return m
}

func ZeroMatrix(rows, cols int) *Matrix { return NewMatrix(rows, cols) }

func OnesVec(n int) *Matrix {
	m := NewMatrix(1, n)
	for i := range m.Data { m.Data[i] = 1.0 }
	return m
}

// Matmul: (m,k) x (k,n) -> (m,n)
func Matmul(a, b *Matrix) *Matrix {
	if a.Cols != b.Rows {
		panic("matmul dim mismatch")
	}
	out := NewMatrix(a.Rows, b.Cols)
	for i := 0; i < a.Rows; i++ {
		for k := 0; k < a.Cols; k++ {
			av := a.At(i, k)
			if av == 0 { continue }
			for j := 0; j < b.Cols; j++ {
				out.Data[i*b.Cols+j] += av * b.At(k, j)
			}
		}
	}
	return out
}

func Transpose(a *Matrix) *Matrix {
	out := NewMatrix(a.Cols, a.Rows)
	for i := 0; i < a.Rows; i++ {
		for j := 0; j < a.Cols; j++ {
			out.Set(j, i, a.At(i, j))
		}
	}
	return out
}

func AddMat(a, b *Matrix) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] + b.Data[i] }
	return out
}

func SubMat(a, b *Matrix) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] - b.Data[i] }
	return out
}

func ScaleMat(a *Matrix, s float32) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] * s }
	return out
}

func MulElem(a, b *Matrix) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] * b.Data[i] }
	return out
}

func DivElem(a, b *Matrix) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] / b.Data[i] }
	return out
}

func SqrtMat(a *Matrix) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = float32(math.Sqrt(float64(a.Data[i]))) }
	return out
}

func Pow2Mat(a *Matrix) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] * a.Data[i] }
	return out
}

func AddScalarMat(a *Matrix, s float32) *Matrix {
	out := NewMatrix(a.Rows, a.Cols)
	for i := range out.Data { out.Data[i] = a.Data[i] + s }
	return out
}

// Softmax row-wise
func SoftmaxRows(m *Matrix) *Matrix {
	out := NewMatrix(m.Rows, m.Cols)
	for r := 0; r < m.Rows; r++ {
		maxv := float32(math.Inf(-1))
		for c := 0; c < m.Cols; c++ {
			if v := m.At(r, c); v > maxv { maxv = v }
		}
		var sum float32
		for c := 0; c < m.Cols; c++ {
			v := float32(math.Exp(float64(m.At(r, c) - maxv)))
			out.Set(r, c, v)
			sum += v
		}
		for c := 0; c < m.Cols; c++ { out.Set(r, c, out.At(r, c)/sum) }
	}
	return out
}

// Softmax single row vector (1 x n)
func Softmax1D(v *Matrix) *Matrix { return SoftmaxRows(v) }

// LayerNorm row-wise: (x - mean) / sqrt(var + eps) * scale + bias
func LayerNormRows(x, scale, bias *Matrix, eps float32) *Matrix {
	out := NewMatrix(x.Rows, x.Cols)
	for r := 0; r < x.Rows; r++ {
		var mean, variance float32
		for c := 0; c < x.Cols; c++ { mean += x.At(r, c) }
		mean /= float32(x.Cols)
		for c := 0; c < x.Cols; c++ {
			d := x.At(r, c) - mean
			variance += d * d
		}
		variance /= float32(x.Cols)
		inv := float32(1.0 / math.Sqrt(float64(variance+eps)))
		for c := 0; c < x.Cols; c++ {
			norm := (x.At(r, c) - mean) * inv
			out.Set(r, c, norm*scale.Data[c]+bias.Data[c])
		}
	}
	return out
}

// GELU approximation
func GeluMat(m *Matrix) *Matrix {
	out := NewMatrix(m.Rows, m.Cols)
	for i, v := range m.Data {
		// 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715*x^3)))
		x := float64(v)
		inner := math.Sqrt(2.0/math.Pi) * (x + 0.044715*x*x*x)
		out.Data[i] = float32(0.5 * x * (1 + math.Tanh(inner)))
	}
	return out
}

// Causal mask: upper triangle = -1e9
func CausalMask(seq int) *Matrix {
	m := NewMatrix(seq, seq)
	for i := 0; i < seq; i++ {
		for j := 0; j < seq; j++ {
			if j > i { m.Set(i, j, -1e9) }
		}
	}
	return m
}

// Row of matrix as 1xCols matrix
func RowVec(m *Matrix, r int) *Matrix {
	out := NewMatrix(1, m.Cols)
	copy(out.Data, m.Data[r*m.Cols:(r+1)*m.Cols])
	return out
}

func SetRow(m *Matrix, r int, v *Matrix) {
	copy(m.Data[r*m.Cols:(r+1)*m.Cols], v.Data)
}

func Argmax(v *Matrix) int {
	best, bestIdx := float32(math.Inf(-1)), 0
	for i, x := range v.Data {
		if x > best { best = x; bestIdx = i }
	}
	return bestIdx
}
