		if strings.HasPrefix(line, "vocab_size=") { continue }
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 { continue }
		idx, _ := strconv.Atoi(parts[0])
		byteVal, _ := strconv.Atoi(parts[1])
		v.ByteToIdx[byteVal] = idx
		if idx >= len(v.IdxToByte) {
			v.IdxToByte = append(v.IdxToByte, make([]byte, idx-len(v.IdxToByte)+1)...)
		}
		v.IdxToByte[idx] = byte(byteVal)
		if idx+1 > v.Size { v.Size = idx + 1 }
	}
	return v, nil
}

func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		idx := v.ByteToIdx[text[i]]
		if idx >= 0 { ids = append(ids, idx) }
	}
	return ids
}

func decode(ids []int, v *Vocab) string {
	out := make([]byte, len(ids))
	for i, id := range ids {
		if id < len(v.IdxToByte) { out[i] = v.IdxToByte[id] }
	}
	return string(out)
}

// Numerical gradient for a matrix parameter
func numGrad(p *model.GPTParams, param *model.Matrix, ids []int, target int, eps float32) *model.Matrix {
	grad := model.NewMatrix(param.Rows, param.Cols)
	orig := param.Clone()
	for i := range param.Data {
		orig.Data[i] += eps
		param.Data[i] = orig.Data[i]
		lp := model.CELoss(model.Forward(p, ids), target)

		orig.Data[i] -= 2 * eps
		param.Data[i] = orig.Data[i]
		lm := model.CELoss(model.Forward(p, ids), target)

		grad.Data[i] = (lp - lm) / (2 * eps)
		orig.Data[i] += eps
		param.Data[i] = orig.Data[i]
	}
	return grad
}

