	params := model.NewGPTParams(cfg)

	// Adam states — only train LMBias + LMHead for speed
	// Full backprop would be needed for all layers; we use numerical diff on lm params
	adamLMBias := newAdam(1, cfg.VocabSize)
	adamLMHead := newAdam(cfg.DModel, cfg.VocabSize)

	lr := float32(0.01)
	b1, b2, epsAdam := float32(0.9), float32(0.999), float32(1e-8)
	fdEps := float32(0.001)

	nEpochs := 200
	batchSize := 8
