	fmt.Printf("epochs=%d, batch=%d, seq=%d, lr=%g\n\n", nEpochs, batchSize, seqLen, lr)

	for epoch := 0; epoch < nEpochs; epoch++ {
		var totalLoss float32
		for b := 0; b < batchSize; b++ {
			// random window
			maxStart := len(corpus) - seqLen - 1
			if maxStart <= 0 { maxStart = 1 }
			start := rand.Intn(maxStart)
			ids := corpus[start : start+seqLen]
			target := corpus[start+seqLen]

			loss := model.CELoss(model.Forward(params, ids), target)
