			// numerical grad for lm_bias (vocab-dim, fast)
			gBias := numGrad(params, params.LMBias, ids, target, fdEps)
			params.LMBias = adamUpdate(params.LMBias, gBias, adamLMBias, lr, b1, b2, epsAdam)

			// numerical grad for lm_head (dmodel x vocab, slower but more powerful)
			if epoch%5 == 0 && b == 0 {
