				params.LMHead = adamUpdate(params.LMHead, gHead, adamLMHead, lr, b1, b2, epsAdam)
			}
		}
		avgLoss := totalLoss / float32(batchSize)

		if epoch%20 == 0 || epoch == nEpochs-1 {
			fmt.Printf("epoch %3d | loss %.4f | ppl %.2f\n", epoch, avgLoss, math.Exp(float64(avgLoss)))
