	writeMatrix(w, "final_ln_bias", p.FinalLnBias)
	writeMatrix(w, "lm_head", p.LMHead)
	writeMatrix(w, "lm_bias", p.LMBias)
	w.Flush()
}

func writeMatrix(w *bufio.Writer, name string, m *model.Matrix) {
	fmt.Fprintf(w, "%s %d %d\n", name, m.Rows, m.Cols)
	sb := &strings.Builder{}
	for i, v := range m.Data {
		if i > 0 { sb.WriteByte(' ') }
		fmt.Fprintf(sb, "%.6g", v)
	}
	fmt.Fprintln(w, sb.String())
}
