}

func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		if idx := v.ByteToIdx[text[i]]; idx >= 0 { ids = append(ids, idx) }
	}
	return ids
}

// Backprop through LM head + final layer norm (simplified)
// Returns gradient w.r.t. hidden state, LMHead grad, LMBias grad
func lmHeadBackward(hidden, lmHead, lmBias *model.Matrix, target int, vocabSize int) (*model.Matrix, *model.Matrix, *model.Matrix) {
	// Forward
	logits := model.Matmul(hidden, lmHead)
	for c := 0; c < vocabSize; c++ { logits.Data[c] += lmBias.Data[c] }
	probs := model.Softmax1D(logits)

	// dLogits = probs - one_hot(target)
	dLogits := probs.Clone()
	dLogits.Data[target] -= 1.0

	// dLMHead = hidden^T @ dLogits
	dLMHead := model.Matmul(model.Transpose(hidden), dLogits)

	// dLMBias = dLogits (sum over batch=1)
	dLMBias := dLogits.Clone()

	// dHidden = dLogits @ lmHead^T
	dHidden := model.Matmul(dLogits, model.Transpose(lmHead))

	return dHidden, dLMHead, dLMBias
}

// Numerical gradient for attention/ffn block params (only for embedding layers)
func numGradMatrix(p *model.GPTParams, param *model.Matrix, ids []int, target int, eps float32) *model.Matrix {
	grad := model.NewMatrix(param.Rows, param.Cols)
	for i := range param.Data {
		orig := param.Data[i]
		param.Data[i] = orig + eps
		lp := model.CELoss(model.Forward(p, ids), target)
		param.Data[i] = orig - eps
		lm := model.CELoss(model.Forward(p, ids), target)
		grad.Data[i] = (lp - lm) / (2 * eps)
		param.Data[i] = orig
	}
	return grad
}

func writeMatrix(w *bufio.Writer, name string, m *model.Matrix) {
	fmt.Fprintf(w, "%s %d %d\n", name, m.Rows, m.Cols)
	sb := &strings.Builder{}
	for i, v := range m.Data {
		if i > 0 { sb.WriteByte(' ') }
		fmt.Fprintf(sb, "%.6g", v)
	}
	fmt.Fprintln(w, sb.String())
}

func saveModel(p *model.GPTParams, path string) {
	f, _ := os.Create(path)
	defer f.Close()
	w := bufio.NewWriter(f)
	cfg := p.Cfg
	fmt.Fprintf(w, "vocab=%d dmodel=%d layers=%d seq=%d ffn=%d\n",
