	seqLen := cfg.SeqLen
	logInterval := 500

	fmt.Printf("\n=== FreeLang LLM Training (backprop on LM head) ===\n")
	fmt.Printf("steps=%d, seq=%d, lr=%g\n\n", nSteps, seqLen, lr)

	var sumLoss float32
	for step := 1; step <= nSteps; step++ {
		maxStart := len(corpus) - seqLen - 1
		if maxStart <= 0 { maxStart = 1 }
		start := rand.Intn(maxStart)
		ids := corpus[start : start+seqLen]
