}

// getLastHidden: forward pass returning only the last hidden state
func getLastHidden(p *model.GPTParams, ids []int) *model.Matrix {
	cfg := p.Cfg
	seq := len(ids)
	x := model.NewMatrix(seq, cfg.DModel)
	for i, id := range ids {
		row := model.RowVec(p.TokenEmb, id)
		posRow := model.RowVec(p.PosEmb, i)
		model.SetRow(x, i, model.AddMat(row, posRow))
	}
	for _, bp := range p.Blocks {
		x1 := model.LayerNormRows(x, bp.Ln1Scale, bp.Ln1Bias, 1e-5)
		// simplified attention (just using x1 directly for now)
		attn := blockForward(x1, bp, seq, cfg.DModel, cfg.FFNDim)
		x = model.AddMat(x, attn)
		x2 := model.LayerNormRows(x, bp.Ln2Scale, bp.Ln2Bias, 1e-5)
		ff := ffnForward(x2, bp, seq)
		x = model.AddMat(x, ff)
	}
	lastRow := model.RowVec(x, seq-1)
	return model.LayerNormRows(lastRow, p.FinalLnScale, p.FinalLnBias, 1e-5)
}

func blockForward(x *model.Matrix, bp model.BlockParams, seq, d, fd int) *model.Matrix {
	Q := linearFwd(x, bp.Wq, bp.Bq, seq)
	K := linearFwd(x, bp.Wk, bp.Bk, seq)
	V := linearFwd(x, bp.Wv, bp.Bv, seq)
	scale := float32(1.0 / math.Sqrt(float64(d)))
	scores := model.AddMat(model.ScaleMat(model.Matmul(Q, model.Transpose(K)), scale), model.CausalMask(seq))
	attnW := model.SoftmaxRows(scores)
	ctx := model.Matmul(attnW, V)
	return linearFwd(ctx, bp.Wo, bp.Bo, seq)
}

func ffnForward(x *model.Matrix, bp model.BlockParams, seq int) *model.Matrix {
	h := linearFwd(x, bp.W1, bp.B1, seq)
	h = model.GeluMat(h)
	return linearFwd(h, bp.W2, bp.B2, seq)
}

func linearFwd(x, W, b *model.Matrix, seq int) *model.Matrix {
	out := model.Matmul(x, W)
	for r := 0; r < seq; r++ {
		for c := 0; c < out.Cols; c++ {
			out.Data[r*out.Cols+c] += b.Data[c]
		}
	}
	return out
}
