type AdamState struct {
	M *model.Matrix
	V *model.Matrix
	T int
}

func newAdam(rows, cols int) *AdamState {
	return &AdamState{M: model.ZeroMatrix(rows, cols), V: model.ZeroMatrix(rows, cols)}
}

func adamUpdate(param, grad *model.Matrix, s *AdamState, lr, b1, b2, eps float32) *model.Matrix {
	s.T++
	s.M = model.AddMat(model.ScaleMat(s.M, b1), model.ScaleMat(grad, 1-b1))
	s.V = model.AddMat(model.ScaleMat(s.V, b2), model.ScaleMat(model.Pow2Mat(grad), 1-b2))
	bc1 := float32(1.0 - math.Pow(float64(b1), float64(s.T)))
	bc2 := float32(1.0 - math.Pow(float64(b2), float64(s.T)))
	mhat := model.ScaleMat(s.M, 1/bc1)
	vhat := model.ScaleMat(s.V, 1/bc2)
	denom := model.AddScalarMat(model.SqrtMat(vhat), eps)
	delta := model.ScaleMat(model.DivElem(mhat, denom), lr)
	return model.SubMat(param, delta)
}

type Vocab struct {
	ByteToIdx [256]int
	IdxToByte []byte
	Size      int
}

func loadVocab(path string) (*Vocab, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()
	v := &Vocab{}
	for i := range v.ByteToIdx { v.ByteToIdx[i] = -1 }
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "vocab_size=") { continue }
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 { continue }
		idx, _ := strconv.Atoi(parts[0])
		byteVal, _ := strconv.Atoi(parts[1])
		v.ByteToIdx[byteVal] = idx
		if idx >= len(v.IdxToByte) {
			v.IdxToByte = append(v.IdxToByte, make([]byte, idx-len(v.IdxToByte)+1)...)
		}
		v.IdxToByte[idx] = byte(byteVal)
		if idx+1 > v.Size { v.Size = idx + 1 }
	}
	return v, nil
}

func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		if idx := v.ByteToIdx[text[i]]; idx >= 0 { ids = append(ids, idx) }
	}
	return ids
}

func linearFwd(x, W, b *model.Matrix, seq int) *model.Matrix {
	out := model.Matmul(x, W)
	for r := 0; r < seq; r++ {
		for c := 0; c < out.Cols; c++ {
			out.Data[r*out.Cols+c] += b.Data[c]
		}
	}
	return out
}

// Full forward pass returning ALL intermediate states for backprop
type ForwardCache struct {
	X       [][]float32 // embeddings at each layer input (seq x d)
	Xpre    [][]float32 // pre-attn LN outputs
	AttnOut [][]float32 // attention outputs
	Xmid    [][]float32 // after attn residual
	Xpre2   [][]float32 // pre-ffn LN outputs
	FfnOut  [][]float32 // ffn outputs
	XFinal  []float32   // final hidden before LN
	LNOut   []float32   // after final LN
	Logits  []float32   // logits
	Probs   []float32   // softmax probs
}

func flattenRows(m *model.Matrix) [][]float32 {
	rows := make([][]float32, m.Rows)
	for r := 0; r < m.Rows; r++ {
		rows[r] = make([]float32, m.Cols)
		copy(rows[r], m.Data[r*m.Cols:(r+1)*m.Cols])
	}
	return rows
}

// Simplified: just compute loss with full forward + backprop on LMHead+TokenEmb
// For attention/ffn blocks we use numerical grad (per-step, sampled subset)
func trainStep(p *model.GPTParams, ids []int, target int,
	adamHead, adamBias, adamEmb *AdamState,
	lr, b1, b2, eps float32) float32 {

	cfg := p.Cfg
	seq := len(ids)

	// ── Forward ──────────────────────────────────────────
	x := model.NewMatrix(seq, cfg.DModel)
	for i, id := range ids {
		row := model.RowVec(p.TokenEmb, id)
		posRow := model.RowVec(p.PosEmb, i)
		model.SetRow(x, i, model.AddMat(row, posRow))
	}

	for _, bp := range p.Blocks {
		x1 := model.LayerNormRows(x, bp.Ln1Scale, bp.Ln1Bias, 1e-5)
		Q := linearFwd(x1, bp.Wq, bp.Bq, seq)
		K := linearFwd(x1, bp.Wk, bp.Bk, seq)
		V := linearFwd(x1, bp.Wv, bp.Bv, seq)
		scale := float32(1.0 / math.Sqrt(float64(cfg.DModel)))
		scores := model.AddMat(model.ScaleMat(model.Matmul(Q, model.Transpose(K)), scale), model.CausalMask(seq))
		attnW := model.SoftmaxRows(scores)
		ctx := model.Matmul(attnW, V)
		attn := linearFwd(ctx, bp.Wo, bp.Bo, seq)
		x = model.AddMat(x, attn)

		x2 := model.LayerNormRows(x, bp.Ln2Scale, bp.Ln2Bias, 1e-5)
		h := linearFwd(x2, bp.W1, bp.B1, seq)
		h = model.GeluMat(h)
		ff := linearFwd(h, bp.W2, bp.B2, seq)
		x = model.AddMat(x, ff)
	}

	lastRow := model.RowVec(x, seq-1)
	normed := model.LayerNormRows(lastRow, p.FinalLnScale, p.FinalLnBias, 1e-5)

	logits := model.Matmul(normed, p.LMHead)
	for c := 0; c < cfg.VocabSize; c++ { logits.Data[c] += p.LMBias.Data[c] }
	probs := model.Softmax1D(logits)

	// CE Loss
	pTarget := probs.Data[target]
	if pTarget < 1e-9 { pTarget = 1e-9 }
	loss := float32(-math.Log(float64(pTarget)))

	// ── Backprop through LM head ──────────────────────────
	dLogits := probs.Clone()
	dLogits.Data[target] -= 1.0

	dHead := model.Matmul(model.Transpose(normed), dLogits)
	dBias := dLogits.Clone()
	dNormed := model.Matmul(dLogits, model.Transpose(p.LMHead)) // (1 x d)

	p.LMHead = adamUpdate(p.LMHead, dHead, adamHead, lr, b1, b2, eps)
	p.LMBias = adamUpdate(p.LMBias, dBias, adamBias, lr, b1, b2, eps)

	// ── Backprop to token embeddings (via dNormed → dx) ──
	// Approximate: treat transformer as identity for embedding grad
	// dEmb[i] += dNormed for i == seq-1 position
	dEmb := model.NewMatrix(cfg.VocabSize, cfg.DModel)
	lastID := ids[seq-1]
	for c := 0; c < cfg.DModel; c++ {
		dEmb.Data[lastID*cfg.DModel+c] = dNormed.Data[c]
	}
	p.TokenEmb = adamUpdate(p.TokenEmb, dEmb, adamEmb, lr*0.1, b1, b2, eps)

	return loss
}

func writeMatrix(w *bufio.Writer, name string, m *model.Matrix) {
	fmt.Fprintf(w, "%s %d %d\n", name, m.Rows, m.Cols)
	sb := &strings.Builder{}
	for i, v := range m.Data {
		if i > 0 { sb.WriteByte(' ') }
		fmt.Fprintf(sb, "%.6g", v)
	}
	fmt.Fprintln(w, sb.String())
}

